Action.Str:
var reservation_result = "Unable to determine reservation status. Check the page.";
var response_code = typeof http_response_code === "undefined" ? "" : String(http_response_code);
var page = typeof http_data === "undefined" ? "" : String(http_data);
if (response_code === "200" && /<section[^>]+id=["']booking["']/i.test(page)) {
  var day_classes = page.match(/class=["'][^"']*\bday\b[^"']*["']/ig) || [];
  var available_day = /id=["']booking-schedule["']/i.test(page) &&
    day_classes.some(function (classes) {
      return /\b(normal|today)\b/i.test(classes) &&
        !/\b(full|blank|disabled)\b/i.test(classes);
    });
  if (available_day) {
    reservation_result = "A selectable reservation date appears on the page. Check available times.";
  } else if (/fully booked/i.test(page) && !/id=["']booking-schedule["']/i.test(page)) {
    reservation_result = "No reservation opening shown; the page says fully booked.";
  }
} else if (response_code === "302") {
  reservation_result = "The reservation page redirected to a waiting room. Open it in a browser to check.";
} else if (/queue-it|waiting room/i.test(page)) {
  reservation_result = "The reservation page is in a waiting room. Open it in a browser to check.";
} else if (response_code !== "200") {
  reservation_result = "Reservation check failed (HTTP " + (response_code || "error") + ").";
}

// Boarding-pass layout for the 1 x 2 "Countdown" Widget v2.
// The following Widget v2 action uses %widget_layout as its Custom Layout.
var widget_layout = (function () {
    var hongKongNow = new Date(Date.now() + 8 * 60 * 60 * 1000);
    var today = Date.UTC(
        hongKongNow.getUTCFullYear(),
        hongKongNow.getUTCMonth(),
        hongKongNow.getUTCDate()
    );
    var departure = Date.UTC(2026, 10, 22);
    var days = Math.round((departure - today) / (24 * 60 * 60 * 1000));

    var number = days > 0 ? String(days) : days === 0 ? "TODAY" : "✈";
    var caption = days > 1 ? "DAYS TO GO" : days === 1 ? "DAY TO GO" :
        days === 0 ? "LET'S GO" : "ARRIVED";

    return JSON.stringify({
        type: "Column",
        fillMaxSize: true,
        padding: 4,
        cornerRadius: 18,
        backgroundColor: "#102D38",
        useMaterialYouColors: false,
        horizontalAlignment: "Center",
        verticalAlignment: "Center",
        task: "Hong Kong Countdown",
        children: [
            {
                type: "Text",
                text: "✈ BOARDING",
                color: "#FFC886",
                textSize: 8,
                bold: true,
                maxLines: 1
            },
            { type: "Spacer", isWeighted: true },
            {
                type: "Column",
                horizontalAlignment: "Center",
                children: [
                    {
                        type: "Text",
                        text: "HKG",
                        color: "#FFFFFF",
                        textSize: 28,
                        bold: true,
                        maxLines: 1
                    },
                    {
                        type: "Text",
                        text: "HONG KONG",
                        color: "#9FC3C8",
                        textSize: 8,
                        bold: true,
                        maxLines: 1
                    }
                ]
            },
            { type: "Spacer", isWeighted: true },
            {
                type: "Column",
                horizontalAlignment: "Center",
                children: [
                    {
                        type: "Text",
                        text: number,
                        color: "#FFC886",
                        textSize: days > 0 ? (days >= 100 ? 34 : 48) : 18,
                        bold: true,
                        maxLines: 1
                    },
                    {
                        type: "Text",
                        text: caption,
                        color: "#FFFFFF",
                        textSize: 8,
                        bold: true,
                        maxLines: 1
                    }
                ]
            },
            { type: "Spacer", isWeighted: true },
            {
                type: "Box",
                fillMaxWidth: true,
                height: 1,
                backgroundColor: "#80B6C1"
            },
            {
                type: "Column",
                horizontalAlignment: "Center",
                paddingTop: 4,
                children: [
                    {
                        type: "Text",
                        text: "DEPARTURE",
                        color: "#9FC3C8",
                        textSize: 8,
                        maxLines: 1
                    },
                    {
                        type: "Text",
                        text: "22 NOV 26",
                        color: "#FFFFFF",
                        textSize: 11,
                        bold: true,
                        maxLines: 1
                    }
                ]
            }
        ]
    });
})();

