/* Format bytes to human readable */
String formatDataSize(double bytes) {
    units = new String[] {"", "KB", "MB", "GB", "TB"};
    value = bytes;
    index = 0;
    while (value >= 1000 && index < units.length - 1) {
        value /= 1024;
        index++;
    }
    if (index >= units.length) return "999+ " + units[units.length - 1];
    if (index == 0) return String.format("%.0f B", value);
    return String.format("%.1f %s", value, units[index]);
}

/* Get boundary timestamps based on Mode (0=Daily, 1=Weekly, 2=Monthly) and Offset */
Object[] getBoundaries(int mode, int offset) {
    Calendar startCal = Calendar.getInstance();
    Calendar endCal = Calendar.getInstance();
    String label = "";

    if (mode == 0) { // Daily
        startCal.add(Calendar.DAY_OF_MONTH, -offset);
        endCal.setTimeInMillis(startCal.getTimeInMillis());
        label = new SimpleDateFormat("MMM dd, yyyy").format(startCal.getTime());
    } else if (mode == 1) { // Weekly
        startCal.add(Calendar.WEEK_OF_YEAR, -offset);
        startCal.set(Calendar.DAY_OF_WEEK, startCal.getFirstDayOfWeek());
        endCal.setTimeInMillis(startCal.getTimeInMillis());
        endCal.add(Calendar.DAY_OF_MONTH, 6);
        SimpleDateFormat f = new SimpleDateFormat("MMM dd");
        label = f.format(startCal.getTime()) + " - " + f.format(endCal.getTime());
    } else if (mode == 2) { // Monthly
        startCal.add(Calendar.MONTH, -offset);
        startCal.set(Calendar.DAY_OF_MONTH, 1);
        endCal.setTimeInMillis(startCal.getTimeInMillis());
        endCal.set(Calendar.DAY_OF_MONTH, endCal.getActualMaximum(Calendar.DAY_OF_MONTH));
        label = new SimpleDateFormat("MMMM yyyy").format(startCal.getTime());
    }

    startCal.set(Calendar.HOUR_OF_DAY, 0);
    startCal.set(Calendar.MINUTE, 0);
    startCal.set(Calendar.SECOND, 0);
    startCal.set(Calendar.MILLISECOND, 0);

    endCal.set(Calendar.HOUR_OF_DAY, 23);
    endCal.set(Calendar.MINUTE, 59);
    endCal.set(Calendar.SECOND, 59);
    endCal.set(Calendar.MILLISECOND, 999);

    return new Object[] { new Long(startCal.getTimeInMillis()), new Long(endCal.getTimeInMillis()), label };
}

/* Get specific single-day boundaries for DatePicker */
Object[] getDayBoundaries(Calendar cal) {
    Calendar startCal = Calendar.getInstance();
    startCal.setTimeInMillis(cal.getTimeInMillis());
    startCal.set(Calendar.HOUR_OF_DAY, 0);
    startCal.set(Calendar.MINUTE, 0);
    startCal.set(Calendar.SECOND, 0);
    startCal.set(Calendar.MILLISECOND, 0);

    Calendar endCal = Calendar.getInstance();
    endCal.setTimeInMillis(cal.getTimeInMillis());
    endCal.set(Calendar.HOUR_OF_DAY, 23);
    endCal.set(Calendar.MINUTE, 59);
    endCal.set(Calendar.SECOND, 59);
    endCal.set(Calendar.MILLISECOND, 999);

    String label = new SimpleDateFormat("MMM dd, yyyy").format(startCal.getTime());
    return new Object[] { new Long(startCal.getTimeInMillis()), new Long(endCal.getTimeInMillis()), label };
}

/* Get total data usage for a time range (Device Wide) using Global Context */
Object[] getDataUsageForRange(long startTime, long endTime) {
  networkStatsManager = (NetworkStatsManager) context.getSystemService(Context.NETWORK_STATS_SERVICE);
  mobileBytes = 0L; wifiBytes = 0L;
  try {
    mobileBucket = networkStatsManager.querySummaryForDevice(ConnectivityManager.TYPE_MOBILE, null, startTime, endTime);
    if (mobileBucket != null) mobileBytes = mobileBucket.getRxBytes() + mobileBucket.getTxBytes();
  } catch(Exception e) {}
  try {
    wifiBucket = networkStatsManager.querySummaryForDevice(ConnectivityManager.TYPE_WIFI, null, startTime, endTime);
    if (wifiBucket != null) wifiBytes = wifiBucket.getRxBytes() + wifiBucket.getTxBytes();
  } catch(Exception e) {}
  return new Object[] { new Long(mobileBytes), new Long(wifiBytes) };
}

