    View[] mobileFillBar = new View[1];

    createDashCard.accept(new Object[]{"Total", tvSumTotal, null});
    createDashCard.accept(new Object[]{"Mobile", tvSumMobile, mobileFillBar});
    createDashCard.accept(new Object[]{"WiFi", tvSumWifi, null});
    mainLayout.addView(summaryRow);

    /* --- FILTER OPTIONS ROW (Search, Hide System, Sort) --- */
    filterOptionsRow = new LinearLayout(currentActivity);
    filterOptionsRow.setOrientation(LinearLayout.HORIZONTAL);
    filterOptionsRow.setGravity(Gravity.CENTER_VERTICAL);
    LinearLayout.LayoutParams foParams = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    foParams.setMargins(((Integer)dp.apply(16)).intValue(), 0, ((Integer)dp.apply(16)).intValue(), ((Integer)dp.apply(8)).intValue());
    filterOptionsRow.setLayoutParams(foParams);

    EditText searchInput = new EditText(themedContext);
    searchInput.setHint("Search apps...");
    searchInput.setHintTextColor(textSecondary);
    searchInput.setTextColor(textPrimary);
    searchInput.setTextSize(14);
    searchInput.setMaxLines(1);
    searchInput.setSingleLine(true);
    searchInput.setPadding(((Integer)dp.apply(12)).intValue(), ((Integer)dp.apply(12)).intValue(), ((Integer)dp.apply(12)).intValue(), ((Integer)dp.apply(12)).intValue());
    searchInput.setBackground(createBg.apply(cardBg));
    LinearLayout.LayoutParams searchParams = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.0f);
    searchParams.rightMargin = ((Integer)dp.apply(8)).intValue();
    searchInput.setLayoutParams(searchParams);

    Switch swSys = new Switch(themedContext);
    swSys.setText("Hide Sys.");
    swSys.setTextColor(textPrimary);
    swSys.setTextSize(12);
    swSys.setChecked(false);

    Spinner spSort = new Spinner(themedContext);
    String[] sortTypes = new String[]{"By Total", "By Mobile", "By WiFi"};
    ArrayAdapter sortAdapter = new ArrayAdapter(themedContext, android.R.layout.simple_spinner_item, sortTypes);
    sortAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
    spSort.setAdapter(sortAdapter);

    filterOptionsRow.addView(searchInput);
    filterOptionsRow.addView(swSys);
    filterOptionsRow.addView(spSort);
    mainLayout.addView(filterOptionsRow);


    /* Loading Spinner */
    loadingSpinner = new ProgressBar(themedContext);
    loadingSpinner.setPadding(0, ((Integer)dp.apply(32)).intValue(), 0, ((Integer)dp.apply(32)).intValue());
    mainLayout.addView(loadingSpinner);

    /* Scrollable List */
    scrollView = new ScrollView(currentActivity);
    scrollView.setFillViewport(true); 
    scrollView.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1.0f));
    listContainer = new LinearLayout(currentActivity);
    listContainer.setOrientation(LinearLayout.VERTICAL);
    listContainer.setPadding(((Integer)dp.apply(16)).intValue(), 0, ((Integer)dp.apply(16)).intValue(), ((Integer)dp.apply(150)).intValue());
    scrollView.addView(listContainer);
    mainLayout.addView(scrollView);

    /* --- TASKS --- */
    fetchPerAppData = new Callable() {
      call() {
        long startTime = selectedStartTime[0].longValue();
        long endTime = selectedEndTime[0].longValue();

        networkStatsManager = (NetworkStatsManager) currentActivity.getSystemService(Context.NETWORK_STATS_SERVICE);
        HashMap usageMap = new HashMap();
        NetworkStats.Bucket bucket = new NetworkStats.Bucket();

        Object[] deviceUsage = getDataUsageForRange(startTime, endTime);
        long fetchTotalMobileBytes = ((Long) deviceUsage[0]).longValue();
        long fetchTotalWifiBytes = ((Long) deviceUsage[1]).longValue();

        try {
          NetworkStats mobileStats = networkStatsManager.querySummary(ConnectivityManager.TYPE_MOBILE, null, startTime, endTime);
          while (mobileStats.hasNextBucket()) {
            mobileStats.getNextBucket(bucket);
            int uid = bucket.getUid();
            long bytes = bucket.getRxBytes() + bucket.getTxBytes();
            if (!usageMap.containsKey(new Integer(uid))) usageMap.put(new Integer(uid), new long[]{0L, 0L});
            ((long[])usageMap.get(new Integer(uid)))[0] += bytes;
          }
          mobileStats.close();
        } catch(Exception e) {}

        try {
          NetworkStats wifiStats = networkStatsManager.querySummary(ConnectivityManager.TYPE_WIFI, null, startTime, endTime);
          while (wifiStats.hasNextBucket()) {
            wifiStats.getNextBucket(bucket);
            int uid = bucket.getUid();
            long bytes = bucket.getRxBytes() + bucket.getTxBytes();
            if (!usageMap.containsKey(new Integer(uid))) usageMap.put(new Integer(uid), new long[]{0L, 0L});
            ((long[])usageMap.get(new Integer(uid)))[1] += bytes;
          }
          wifiStats.close();
        } catch(Exception e) {}

        ArrayList fetchUsageList = new ArrayList();
        java.util.Iterator iterator = usageMap.keySet().iterator();

        while (iterator.hasNext()) {
          int uid = ((Integer)iterator.next()).intValue();
          long[] usageData = (long[])usageMap.get(new Integer(uid));
          long mobileBytes = usageData[0];
          long wifiBytes = usageData[1];
          long totalBytes = mobileBytes + wifiBytes;

          String appName = null;
          ApplicationInfo appInfo = null;
          String pkgName = "";

          try {
            String[] packages = packageManager.getPackagesForUid(uid);
            if (packages != null && packages.length > 0) {
              pkgName = packages[0];
              appInfo = packageManager.getApplicationInfo(pkgName, 0);
              appName = appInfo.loadLabel(packageManager).toString();
            }
          } catch(Exception e) {}

          if (appName == null) {
            if (uid == -5) appName = "OEM Tethering / Hotspot";
            else if (uid == -4) appName = "Removed / Uninstalled Apps";
            else if (uid == -2) appName = "USB/Bluetooth Tethering";
            else if (uid == 0) appName = "Android OS (Root / Kernel)";
            else if (uid == 1000) appName = "Android System";
            else if (uid == 1051 || uid == 1052) appName = "DNS Resolver";
            else if (uid > 1000 && uid < 10000) appName = "System Service (" + uid + ")";
            else if (uid < 0) appName = "Kernel Routing / VoLTE (" + uid + ")"; 
            else appName = "Unknown (UID " + uid + ")";
          }

          fetchUsageList.add(new Object[] { appName, new Long(mobileBytes), new Long(wifiBytes), new Long(totalBytes), appInfo, new Integer(uid), pkgName });
        }

        return new Object[] { fetchUsageList, new Long(fetchTotalMobileBytes), new Long(fetchTotalWifiBytes) };
      }
    };

    fetchHistoryData = new Callable() {
      call() {
        ArrayList fetchDailyUsageList = new ArrayList();
        long fetchTotalMobileBytes = 0L;
        long fetchTotalWifiBytes = 0L;

        int hMode = historyMode[0].intValue();
        int maxOffset = (hMode == 0) ? 30 : 12;

        for (int i = 0; i < maxOffset; i++) {
          Object[] bounds = getBoundaries(hMode, i);
          long st = ((Long)bounds[0]).longValue();
          long en = ((Long)bounds[1]).longValue();
          String lbl = (String) bounds[2];

          Object[] usage = getDataUsageForRange(st, en);
          long mobileBytes = ((Long) usage[0]).longValue();
          long wifiBytes = ((Long) usage[1]).longValue();
          long totalBytes = mobileBytes + wifiBytes;

          fetchTotalMobileBytes += mobileBytes;
          fetchTotalWifiBytes += wifiBytes;

          fetchDailyUsageList.add(new Object[] { lbl, new Long(mobileBytes), new Long(wifiBytes), new Long(totalBytes), new Long(st), new Long(en) });
        }
        return new Object[] { fetchDailyUsageList, new Long(fetchTotalMobileBytes), new Long(fetchTotalWifiBytes) };
      }
    };

    fetchAppHistoryData = new Callable() {
      call() {
        ArrayList fetchHistoryList = new ArrayList();
        long fetchTotalMobileBytes = 0L;
        long fetchTotalWifiBytes = 0L;

        networkStatsManager = (NetworkStatsManager) currentActivity.getSystemService(Context.NETWORK_STATS_SERVICE);
        int targetUid = selectedAppUid[0].intValue();
        int hMode = historyMode[0].intValue();
        int maxOffset = (hMode == 0) ? 30 : 12;

        Object[] oldestBounds = getBoundaries(hMode, maxOffset - 1);
        Object[] newestBounds = getBoundaries(hMode, 0);
        long startT = ((Long) oldestBounds[0]).longValue();
        long endT = ((Long) newestBounds[1]).longValue();

        HashMap histMap = new HashMap();

        try {
            NetworkStats mStats = networkStatsManager.queryDetailsForUid(ConnectivityManager.TYPE_MOBILE, null, startT, endT, targetUid);
            NetworkStats.Bucket b = new NetworkStats.Bucket();
            while (mStats.hasNextBucket()) {
                mStats.getNextBucket(b);
                long bTime = b.getStartTimeStamp();
                long bytes = b.getRxBytes() + b.getTxBytes();

                for (int i=0; i<maxOffset; i++) {
                    Object[] bnd = getBoundaries(hMode, i);
                    if (bTime >= ((Long)bnd[0]).longValue() && bTime <= ((Long)bnd[1]).longValue()) {
                        String lbl = (String) bnd[2];
                        if (!histMap.containsKey(lbl)) histMap.put(lbl, new long[]{0L, 0L});
                        ((long[])histMap.get(lbl))[0] += bytes;
                        fetchTotalMobileBytes += bytes;
                        break;
                    }
                }
            }
            mStats.close();
        } catch(Exception e) {}

        try {
            NetworkStats wStats = networkStatsManager.queryDetailsForUid(ConnectivityManager.TYPE_WIFI, null, startT, endT, targetUid);
            NetworkStats.Bucket b = new NetworkStats.Bucket();
            while (wStats.hasNextBucket()) {
                wStats.getNextBucket(b);
                long bTime = b.getStartTimeStamp();
                long bytes = b.getRxBytes() + b.getTxBytes();

                for (int i=0; i<maxOffset; i++) {
                    Object[] bnd = getBoundaries(hMode, i);
                    if (bTime >= ((Long)bnd[0]).longValue() && bTime <= ((Long)bnd[1]).longValue()) {
                        String lbl = (String) bnd[2];
                        if (!histMap.containsKey(lbl)) histMap.put(lbl, new long[]{0L, 0L});
                        ((long[])histMap.get(lbl))[1] += bytes;
                        fetchTotalWifiBytes += bytes;
                        break;
                    }
                }
            }
            wStats.close();
        } catch(Exception e) {}

        for (int i = 0; i < maxOffset; i++) {
            Object[] bounds = getBoundaries(hMode, i);
            String lbl = (String) bounds[2];

            long mBytes = 0L; long wBytes = 0L;
            if (histMap.containsKey(lbl)) {
                mBytes = ((long[])histMap.get(lbl))[0];
                wBytes = ((long[])histMap.get(lbl))[1];
            }

            long tot = mBytes + wBytes;
            fetchHistoryList.add(new Object[] { lbl, new Long(mBytes), new Long(wBytes), new Long(tot) });
        }
        return new Object[] { fetchHistoryList, new Long(fetchTotalMobileBytes), new Long(fetchTotalWifiBytes) };
      }
    };

    /* --- RENDER LOGIC --- */
    Runnable renderDataList = new Runnable() {
        run() {
            if (currentActivity.isFinishing() || currentActivity.isDestroyed()) return;
            listContainer.removeAllViews();
            int mode = currentViewMode[0].intValue();

            ArrayList filtered = new ArrayList();
            long maxLimit = 0L;

            for (int i = 0; i < fullDataList.size(); i++) {
                Object[] item = (Object[]) fullDataList.get(i);

                if (mode == 0) {
                    // System App Filter
                    int uid = ((Integer)item[5]).intValue();
                    if (hideSystemApps[0].booleanValue()) {
                        if (uid < 10000) continue;
                        ApplicationInfo info = (ApplicationInfo) item[4];
                        if (info != null) {
                            boolean isSystem = (info.flags & ApplicationInfo.FLAG_SYSTEM) != 0 || (info.flags & ApplicationInfo.FLAG_UPDATED_SYSTEM_APP) != 0;
                            if (isSystem) continue;
                        } else {
                            continue; // Unidentified UIDs are typically system processes
                        }
                    }

                    // Search Text Filter
                    String search = searchFilterStr[0].toLowerCase();
                    String title = ((String)item[0]).toLowerCase();
                    if (!search.isEmpty() && !title.contains(search)) continue;
                }

                long tot = ((Long)item[3]).longValue();
                if (tot > maxLimit) maxLimit = tot;
                filtered.add(item);
            }

            // Dynamic Sorting
            Collections.sort(filtered, new Comparator() {
              compare(Object o1, Object o2) {
                  int sMode = sortMode[0].intValue();
                  int index = (sMode == 1) ? 1 : (sMode == 2) ? 2 : 3;
                  return Long.compare(((Long)((Object[]) o2)[index]).longValue(), ((Long)((Object[]) o1)[index]).longValue());
              }
            });

            if (filtered.size() == 0) {
                TextView tvEmpty = new TextView(currentActivity);
                tvEmpty.setText("No usage recorded.");
                tvEmpty.setTextColor(textSecondary);
                tvEmpty.setGravity(Gravity.CENTER);
                tvEmpty.setPadding(0, ((Integer)dp.apply(40)).intValue(), 0, 0);
                listContainer.addView(tvEmpty);
            } else {
                for (int i = 0; i < filtered.size(); i++) {
                    Object[] item = (Object[]) filtered.get(i);
                    String title = (String) item[0];
                    long mobile = ((Long) item[1]).longValue();
                    long wifi = ((Long) item[2]).longValue();
                    long total = ((Long) item[3]).longValue();

                    if (mode > 0 && total == 0) continue; // Hide 0 bytes history

                    String subTitle = "";
                    Drawable iconD = null;
                    Integer rowUid = new Integer(0);
                    Long rowStart = null; Long rowEnd = null; String rowLabel = "";
                    String rowPkg = "";

                    if (mode == 0) {
                        subTitle = "UID: " + item[5];
                        rowUid = (Integer) item[5];
                        rowPkg = (String) item[6];

                        ApplicationInfo info = (ApplicationInfo) item[4];
                        iconD = currentActivity.getDrawable(android.R.drawable.sym_def_app_icon);
                        if (info != null) { try { iconD = info.loadIcon(packageManager); } catch(Exception e){} }
                        else { iconD.setTint(textSecondary); }
                    } else if (mode == 1) {
                        rowStart = (Long) item[4];
                        rowEnd = (Long) item[5];
                        rowLabel = title;
                    }

                    // -- Build Row UI --
                    final String fTitle = title;
                    final Drawable fIcon = iconD;
                    final Integer fUid = rowUid;
                    final Long fStart = rowStart;
                    final Long fEnd = rowEnd;
                    final String fLabel = rowLabel;
                    final String fPkg = rowPkg;

                    LinearLayout row = new LinearLayout(currentActivity);
                    row.setOrientation(LinearLayout.HORIZONTAL);
                    row.setGravity(Gravity.CENTER_VERTICAL);
                    row.setBackground(createBg.apply(cardBg));
                    LinearLayout.LayoutParams rowParams = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
                    rowParams.bottomMargin = ((Integer)dp.apply(8)).intValue();
                    row.setLayoutParams(rowParams);
                    row.setPadding(((Integer)dp.apply(16)).intValue(), ((Integer)dp.apply(16)).intValue(), ((Integer)dp.apply(16)).intValue(), ((Integer)dp.apply(16)).intValue());

                    if (iconD != null) {
                        ImageView iv = new ImageView(currentActivity);
                        iv.setImageDrawable(iconD);
                        LinearLayout.LayoutParams ivParams = new LinearLayout.LayoutParams(((Integer)dp.apply(40)).intValue(), ((Integer)dp.apply(40)).intValue());
                        ivParams.rightMargin = ((Integer)dp.apply(16)).intValue();
                        iv.setLayoutParams(ivParams);
                        row.addView(iv);
                    }

                    LinearLayout centerCol = new LinearLayout(currentActivity);
                    centerCol.setOrientation(LinearLayout.VERTICAL);
                    centerCol.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.0f));

                    TextView tvTitle = new TextView(currentActivity);
                    tvTitle.setText(title);
                    tvTitle.setTextColor(textPrimary);
                    tvTitle.setTextSize(15);
                    tvTitle.setTypeface(null, Typeface.BOLD);
                    tvTitle.setMaxLines(1);
                    centerCol.addView(tvTitle);

                    if (!subTitle.isEmpty()) {
                        TextView tvSub = new TextView(currentActivity);
                        tvSub.setText(subTitle);
                        tvSub.setTextColor(textSecondary);
                        tvSub.setTextSize(12);
                        centerCol.addView(tvSub);
                    }

                    // Split Progress Bar
                    if (maxLimit > 0) {
                        FrameLayout barContainer = new FrameLayout(currentActivity);
                        barContainer.setBackgroundColor(dividerColor);
                        if (Build.VERSION.SDK_INT >= 21) barContainer.setClipToOutline(true); 

                        LinearLayout.LayoutParams pbgParams = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ((Integer)dp.apply(6)).intValue());
                        pbgParams.topMargin = ((Integer)dp.apply(8)).intValue();
                        pbgParams.rightMargin = ((Integer)dp.apply(16)).intValue();
                        barContainer.setLayoutParams(pbgParams);

                        LinearLayout fillRow = new LinearLayout(currentActivity);
                        fillRow.setOrientation(LinearLayout.HORIZONTAL);
                        fillRow.setLayoutParams(new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
                        fillRow.setWeightSum(1.0f);

                        float mobPct = (float)mobile / (float)maxLimit;
                        float wifiPct = (float)wifi / (float)maxLimit;
                        if ((mobPct + wifiPct) > 1.0f) {
                            float sum = mobPct + wifiPct;
                            mobPct /= sum; wifiPct /= sum;
                        }

                        if (mobPct > 0) {
                            View mobFill = new View(currentActivity);
                            mobFill.setBackgroundColor(mobileColor);
                            mobFill.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, mobPct));
                            fillRow.addView(mobFill);
                        }
                        if (wifiPct > 0) {
                            View wifiFill = new View(currentActivity);
                            wifiFill.setBackgroundColor(wifiColor);
                            wifiFill.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, wifiPct));
                            fillRow.addView(wifiFill);
                        }

                        barContainer.addView(fillRow);
                        centerCol.addView(barContainer);
                    }

                    row.addView(centerCol);

                    LinearLayout rightCol = new LinearLayout(currentActivity);
                    rightCol.setOrientation(LinearLayout.VERTICAL);
                    rightCol.setGravity(Gravity.RIGHT);

                    TextView tvTot = new TextView(currentActivity);
                    tvTot.setText(formatDataSize(total));
                    tvTot.setTextColor(accentColor);
                    tvTot.setTextSize(15);
                    tvTot.setTypeface(null, Typeface.BOLD);
                    rightCol.addView(tvTot);

                    if (mobile > 0 || wifi > 0) {
                        String mwStr = "";
                        if (mobile > 0) mwStr += "<font color='#4CAF50'>M:</font> " + formatDataSize(mobile);
                        if (wifi > 0) {
                            if (!mwStr.isEmpty()) mwStr += "<br>";
                            mwStr += "<font color='#2196F3'>W:</font> " + formatDataSize(wifi);
                        }
                        TextView tvMW = new TextView(currentActivity);
                        tvMW.setText(android.text.Html.fromHtml(mwStr));
                        tvMW.setTextColor(textSecondary);
                        tvMW.setTextSize(11);
                        tvMW.setGravity(Gravity.RIGHT);
                        rightCol.addView(tvMW);
                    }

                    row.addView(rightCol);

                    // Click Routing
                    if (mode == 0 || mode == 1) {
                        row.setClickable(true);
                        row.setOnClickListener(new View.OnClickListener() {
                            onClick(View v) {
                                if (mode == 0) {
                                    selectedAppUid[0] = fUid;
                                    selectedAppName[0] = fTitle;
                                    selectedAppIconDrawable[0] = fIcon;
                                    selectedAppPackage[0] = fPkg;
                                    historyMode[0] = new Integer(0);
                                    switchViewMode.accept(new Integer(2)); 
                                } else if (mode == 1) {
                                    selectedStartTime[0] = fStart;
                                    selectedEndTime[0] = fEnd;
                                    selectedDateLabel[0] = fLabel;
                                    switchViewMode.accept(new Integer(0));
                                }
                            }
                        });

                        if (mode == 0 && fPkg != null && !fPkg.isEmpty()) {
                            row.setOnLongClickListener(new View.OnLongClickListener() {
                                onLongClick(View v) {
                                    try {
                                        Intent intent = new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS);
                                        intent.setData(Uri.parse("package:" + fPkg));
                                        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                                        currentActivity.startActivity(intent);
                                    } catch (Exception e) {}
                                    return true;
                                }
                                onLongClickUseDefaultHapticFeedback(v) { return true; }
                            });
                        }
                    }

                    listContainer.addView(row);
                }
            }
            attachKeyListeners.accept(mainLayout);
        }
    };

    updateUI = new Consumer() {
      accept(Object result) {
        if (currentActivity.isFinishing() || currentActivity.isDestroyed()) return;
        loadingSpinner.setVisibility(View.GONE);

        Object[] results = (Object[]) result;
        fullDataList = (ArrayList) results[0];
        long totalMob = ((Long) results[1]).longValue();
        long totalWif = ((Long) results[2]).longValue();

        tvSumTotal[0].setText(formatDataSize(totalMob + totalWif));
        tvSumMobile[0].setText(formatDataSize(totalMob));
        tvSumWifi[0].setText(formatDataSize(totalWif));

        if (dataLimitMb > 0 && mobileFillBar[0] != null) {
            double limitBytes = dataLimitMb * 1024.0 * 1024.0;
            float pct = (float) (totalMob / limitBytes);
            if (pct > 1.0f) pct = 1.0f;
            LinearLayout.LayoutParams lp = (LinearLayout.LayoutParams) mobileFillBar[0].getLayoutParams();
            lp.weight = pct;
            mobileFillBar[0].setLayoutParams(lp);
        }

        renderDataList.run();
      }
    };

    onError = new Consumer() {
      accept(Object e) {
        if (currentActivity.isFinishing() || currentActivity.isDestroyed()) return;
        loadingSpinner.setVisibility(View.GONE);
        TextView tvErr = new TextView(currentActivity);
        tvErr.setText("Error: " + ((Throwable) e).getMessage());
        tvErr.setTextColor(Color.RED);
        listContainer.addView(tvErr);
        attachKeyListeners.accept(mainLayout);
      }
    };

    runTaskAsync = new Consumer() {
        accept(Object typeObj) {
            int type = ((Integer)typeObj).intValue();
            new Thread(new Runnable() {
                run() {
                    try {
                        Object res = null;
                        if (type == 0) res = fetchPerAppData.call();
                        else if (type == 1) res = fetchHistoryData.call();
                        else if (type == 2) res = fetchAppHistoryData.call();

                        final Object finalRes = res;
                        currentActivity.runOnUiThread(new Runnable() {
                            run() { updateUI.accept(finalRes); }
                        });
                    } catch (Exception e) {
                        final Exception finalE = e;
                        currentActivity.runOnUiThread(new Runnable() {
                            run() { onError.accept(finalE); }
                        });
                    }
                }
            }).start();
        }
    };

    /* Navigation & Mode Switcher */
    switchViewMode = new Consumer() {
        accept(Object modeObj) {
            int mode = ((Integer)modeObj).intValue();
            currentViewMode[0] = new Integer(mode);

            mainLayout.setFocusableInTouchMode(true);
            mainLayout.requestFocus();

            listContainer.removeAllViews();
            tvSumTotal[0].setText("...");
            tvSumMobile[0].setText("...");
            tvSumWifi[0].setText("...");
            loadingSpinner.setVisibility(View.VISIBLE);

            if (mode == 0) { 
                tabBar.setVisibility(View.VISIBLE);
                navBar.setVisibility(View.GONE);
                historyFilterBar.setVisibility(View.GONE);
                filterOptionsRow.setVisibility(View.VISIBLE);

                tvTabApp.setBackground(createBg.apply(accentColor));
                tvTabApp.setTextColor(Color.WHITE);
                tvTabDay.setBackgroundColor(Color.TRANSPARENT);
                tvTabDay.setTextColor(textSecondary);

                dateBar.setVisibility(View.VISIBLE);
                dateTextView.setText(selectedDateLabel[0]);
                runTaskAsync.accept(new Integer(0));

            } else if (mode == 1 || mode == 2) {
                dateBar.setVisibility(View.GONE);
                historyFilterBar.setVisibility(View.VISIBLE);
                filterOptionsRow.setVisibility(View.GONE);

                if (mode == 1) { // Device History
                    tabBar.setVisibility(View.VISIBLE);
                    navBar.setVisibility(View.GONE);
                    tvTabDay.setBackground(createBg.apply(accentColor));
                    tvTabDay.setTextColor(Color.WHITE);
                    tvTabApp.setBackgroundColor(Color.TRANSPARENT);
                    tvTabApp.setTextColor(textSecondary);
                } else { // Single App History
                    tabBar.setVisibility(View.GONE);
                    navBar.setVisibility(View.VISIBLE);
                    navAppText.setText(selectedAppName[0]);
                    navAppIcon.setImageDrawable(selectedAppIconDrawable[0]);

                    if (selectedAppPackage[0] != null && !selectedAppPackage[0].isEmpty()) {
                        navInfoBtn.setVisibility(View.VISIBLE);
                    } else {
                        navInfoBtn.setVisibility(View.GONE);
                    }
                }

                int hMode = historyMode[0].intValue();
                tvHistDaily.setBackground(hMode == 0 ? createBg.apply(accentColor) : null);
                tvHistDaily.setTextColor(hMode == 0 ? Color.WHITE : textSecondary);
                tvHistWeekly.setBackground(hMode == 1 ? createBg.apply(accentColor) : null);
                tvHistWeekly.setTextColor(hMode == 1 ? Color.WHITE : textSecondary);
                tvHistMonthly.setBackground(hMode == 2 ? createBg.apply(accentColor) : null);
                tvHistMonthly.setTextColor(hMode == 2 ? Color.WHITE : textSecondary);

                runTaskAsync.accept(new Integer(mode));
            }
        }
    };

    /* Click Listeners */
    tvTabApp.setOnClickListener(new View.OnClickListener() { onClick(View v) { if(currentViewMode[0].intValue() != 0) switchViewMode.accept(new Integer(0)); } });
    tvTabDay.setOnClickListener(new View.OnClickListener() { onClick(View v) { if(currentViewMode[0].intValue() != 1) { historyMode[0] = new Integer(0); switchViewMode.accept(new Integer(1)); } } });
    backIcon.setOnClickListener(new View.OnClickListener() { onClick(View v) { switchViewMode.accept(new Integer(0)); } });

    tvHistDaily.setOnClickListener(new View.OnClickListener() { onClick(View v) { historyMode[0] = new Integer(0); switchViewMode.accept(currentViewMode[0]); } });
    tvHistWeekly.setOnClickListener(new View.OnClickListener() { onClick(View v) { historyMode[0] = new Integer(1); switchViewMode.accept(currentViewMode[0]); } });
    tvHistMonthly.setOnClickListener(new View.OnClickListener() { onClick(View v) { historyMode[0] = new Integer(2); switchViewMode.accept(currentViewMode[0]); } });

    searchInput.addTextChangedListener(new TextWatcher() {
        beforeTextChanged(CharSequence s, int start, int count, int after) {}
        onTextChanged(CharSequence s, int start, int before, int count) {}
        afterTextChanged(Editable s) {
            searchFilterStr[0] = s.toString();
            renderDataList.run();
        }
    });

    swSys.setOnCheckedChangeListener(new android.widget.CompoundButton.OnCheckedChangeListener() {
        onCheckedChanged(android.widget.CompoundButton buttonView, boolean isChecked) {
            hideSystemApps[0] = new Boolean(isChecked);
            renderDataList.run();
        }
    });

    spSort.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
        onItemSelected(AdapterView parent, View view, int position, long id) {
            sortMode[0] = new Integer(position);
            renderDataList.run();
        }
        onNothingSelected(AdapterView parent) {}
    });

    dateClickListener = new View.OnClickListener() {
      onClick(View v) {
        Calendar pickCal = Calendar.getInstance();
        new DatePickerDialog(themedContext, new DatePickerDialog.OnDateSetListener() {
          onDateSet(DatePicker view, int year, int month, int dayOfMonth) {
            pickCal.set(year, month, dayOfMonth);
            Object[] bnd = getDayBoundaries(pickCal);
            selectedStartTime[0] = (Long) bnd[0];
            selectedEndTime[0] = (Long) bnd[1];
            selectedDateLabel[0] = (String) bnd[2];
            switchViewMode.accept(new Integer(0));
          }
        }, pickCal.get(Calendar.YEAR), pickCal.get(Calendar.MONTH), pickCal.get(Calendar.DAY_OF_MONTH)).show();
      }
    };
    dateBar.setOnClickListener(dateClickListener);

    // Boot
    switchViewMode.accept(new Integer(0));
    currentActivity.setContentView(mainLayout);
    currentActivity.getWindow().setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT);
    attachKeyListeners.accept(mainLayout);
  }
};

tasker.doWithActivity(activityConsumer);

if (networkSpeedStop == null || networkSpeedStop == void) {
    tasker.logAndToast("Network Speed does not appear to be running.");
    return;
}

try {

    /* Tell the subject that it has completed, which will unblock the logger script. */
networkSpeedStop.onComplete();

    tasker.setJavaVariable("networkSpeedStop", null);

    tasker.logAndToast("Stop signal sent.");
} catch (Exception e) {
    tasker.logAndToast("Error trying to stop Network Speed: " + e.getMessage());
}

