getIndicatorIcon(String speedValue, String speedUnit) {
    float scale = notifIconScale / 100f;
    mIconCanvas.drawColor(Color.TRANSPARENT, PorterDuff.Mode.CLEAR);
    mIconCanvas.save();
    mIconCanvas.scale(scale, scale, 48, 48);

    if (speedValue.length() == 3 && !speedValue.contains(".")) mIconSpeedPaint.setTextScaleX(0.8f);
    else mIconSpeedPaint.setTextScaleX(0.9f);

    mIconCanvas.drawText(speedValue, 48, 52, mIconSpeedPaint);
    mIconCanvas.drawText(speedUnit, 48, 95, mIconUnitPaint);

    mIconCanvas.restore();
    return Icon.createWithBitmap(mIconBitmap);
};

