int getAlignGravity(int align) {
    int g = Gravity.TOP;
    if (align >= 1 && align <= 3) g |= Gravity.CENTER_HORIZONTAL;
    else if (align == 4) g |= Gravity.RIGHT; // 4 = Left of Cutout, anchored to right edge
    else g |= Gravity.LEFT; // Covers 0 (Custom), 5 (Right of Cutout)
    return g;
}

int getAlignX(int align, int manualX) {
    if (align == 0) return manualX;
    if (mOverlayWindowManager == null) return 0;
    DisplayMetrics metrics = new DisplayMetrics(); mOverlayWindowManager.getDefaultDisplay().getRealMetrics(metrics);
    if (align == 1) return -(metrics.widthPixels / 4);
    if (align == 2) return 0;
    if (align == 3) return (metrics.widthPixels / 4);
    return 0; // 4 and 5 will be dynamically corrected in updateOverlayBackground once width is known
}

/* Dynamic Background Updater */
updateOverlayBackground = new Runnable() {
    run() {
        if (mOverlayWindowManager == null) return;
        DisplayMetrics metrics = new DisplayMetrics();
        mOverlayWindowManager.getDefaultDisplay().getRealMetrics(metrics);

        int bgColor = Color.parseColor("#88000000"); if (useCustomColors) try { bgColor = Color.parseColor(colorBgStr); } catch (Exception e) {}
        float r = bgRadius;

        // 1. Precise Hardware Cutout Detection
        if (Build.VERSION.SDK_INT >= 30) {
            try {
                WindowMetrics wMetrics = mOverlayWindowManager.getMaximumWindowMetrics();
                WindowInsets insets = wMetrics.getWindowInsets();
                android.view.DisplayCutout dc = insets.getDisplayCutout();
                if (dc != null) {
                    java.util.List rects = dc.getBoundingRects();
                    if (rects != null && rects.size() > 0) deviceCutout = (Rect) rects.get(0);
                }
            } catch (Exception e) {}
        } else if (Build.VERSION.SDK_INT >= 28 && mMeasureView != null) {
            WindowInsets insets = mMeasureView.getRootWindowInsets();
            if (insets != null) {
                android.view.DisplayCutout dc = insets.getDisplayCutout();
                if (dc != null) {
                    java.util.List rects = dc.getBoundingRects();
                    if (rects != null && rects.size() > 0) deviceCutout = (Rect) rects.get(0);
                }
            }
        }

        // Draw Shared Graph
        boolean anyGraph = (useO1 && o1Graph) || (useO2 && o2Graph);
        if (anyGraph && graphHistory.size() > 1) {
            int gColor = Color.parseColor("#90FFFFFF"); if (useCustomColors) try { gColor = Color.parseColor(colorGraphStr); } catch (Exception e) {}
            graphPaint.setColor(gColor);
            graphCanvas.drawColor(Color.TRANSPARENT, PorterDuff.Mode.CLEAR);
            Path p = new Path(); float maxV = 1024f;
            for(int i=0; i<graphHistory.size(); i++) { float v = ((Float)graphHistory.get(i)).floatValue(); if(v > maxV) maxV = v; }
            float stepX = 500f / 29f;
            for(int i=0; i<graphHistory.size(); i++) {
                float v = ((Float)graphHistory.get(i)).floatValue(); float x = i * stepX; float y = 150f - ((v / maxV) * 120f) - 15f; 
                if(i == 0) p.moveTo(x, y); else p.lineTo(x, y);
            }
            graphCanvas.drawPath(p, graphPaint);
        }

        // Apply to Overlay 1
        if (mOverlayRoot1 != null && mOverlayParams1 != null && mOverlayView1 != null) {
            int vw = mOverlayView1.getWidth(); int vh = mOverlayView1.getHeight();
            if (vw > 0 && vh > 0) {
                // Perfect, jitter-free Anchor offset using WindowManager edges
                if (o1Align == 4 || o1Align == 5) {
                    if (deviceCutout != null) {
                        int newX = mOverlayParams1.x;
                        if (o1Align == 4) newX = metrics.widthPixels - deviceCutout.left + 15; // Gravity.RIGHT
                        if (o1Align == 5) newX = deviceCutout.right + 15; // Gravity.LEFT

                        if (mOverlayParams1.x != newX) {
                            mOverlayParams1.x = newX;
                            mOverlayWindowManager.updateViewLayout(mOverlayRoot1, mOverlayParams1);
                        }
                    }
                }

                FrameLayout.LayoutParams bgP = (FrameLayout.LayoutParams) mOverlayBgView1.getLayoutParams();
                if (bgP.width != vw || bgP.height != vh) { bgP.width = vw; bgP.height = vh; mOverlayBgView1.setLayoutParams(bgP); }
                FrameLayout.LayoutParams grP = (FrameLayout.LayoutParams) mGraphView1.getLayoutParams();
                if (grP.width != vw || grP.height != vh) { grP.width = vw; grP.height = vh; mGraphView1.setLayoutParams(grP); }

                float tl = r, tr = r, bl = r, br = r;
                if (mOverlayParams1.y <= 0) { tl = 0; tr = 0; }
                if (mOverlayParams1.y + vh >= metrics.heightPixels) { bl = 0; br = 0; }

                int hGrav1 = mOverlayParams1.gravity & Gravity.HORIZONTAL_GRAVITY_MASK;
                int absLeft = mOverlayParams1.x;
                if (hGrav1 == Gravity.CENTER_HORIZONTAL) {
                    absLeft = (metrics.widthPixels / 2) + mOverlayParams1.x - (vw / 2);
                } else if (hGrav1 == Gravity.RIGHT) {
                    absLeft = metrics.widthPixels - mOverlayParams1.x - vw;
                }
                if (absLeft <= 0) { tl = 0; bl = 0; }
                if (absLeft + vw >= metrics.widthPixels) { tr = 0; br = 0; }

                GradientDrawable gd = new GradientDrawable(); gd.setColor(bgColor); gd.setCornerRadii(new float[]{tl, tl, tr, tr, br, br, bl, bl});
                mOverlayBgView1.setBackground(gd);

                if (o1Graph && graphHistory.size() > 1) { mGraphView1.setImageBitmap(graphBitmap); mGraphView1.invalidate(); } 
                else mGraphView1.setImageDrawable(null);
            } else mOverlayRoot1.postDelayed(updateOverlayBackground, 50); 
        }

        // Apply to Overlay 2
        if (mOverlayRoot2 != null && mOverlayParams2 != null && mOverlayView2 != null) {
            int vw = mOverlayView2.getWidth(); int vh = mOverlayView2.getHeight();
            if (vw > 0 && vh > 0) {
                // Perfect, jitter-free Anchor offset using WindowManager edges
                if (o2Align == 4 || o2Align == 5) {
                    if (deviceCutout != null) {
                        int newX = mOverlayParams2.x;
                        if (o2Align == 4) newX = metrics.widthPixels - deviceCutout.left + 15; // Gravity.RIGHT
                        if (o2Align == 5) newX = deviceCutout.right + 15; // Gravity.LEFT

                        if (mOverlayParams2.x != newX) {
                            mOverlayParams2.x = newX;
                            mOverlayWindowManager.updateViewLayout(mOverlayRoot2, mOverlayParams2);
                        }
                    }
                }

                FrameLayout.LayoutParams bgP = (FrameLayout.LayoutParams) mOverlayBgView2.getLayoutParams();
                if (bgP.width != vw || bgP.height != vh) { bgP.width = vw; bgP.height = vh; mOverlayBgView2.setLayoutParams(bgP); }
                FrameLayout.LayoutParams grP = (FrameLayout.LayoutParams) mGraphView2.getLayoutParams();
                if (grP.width != vw || grP.height != vh) { grP.width = vw; grP.height = vh; mGraphView2.setLayoutParams(grP); }

                float tl = r, tr = r, bl = r, br = r;
                if (mOverlayParams2.y <= 0) { tl = 0; tr = 0; }
                if (mOverlayParams2.y + vh >= metrics.heightPixels) { bl = 0; br = 0; }

                int hGrav2 = mOverlayParams2.gravity & Gravity.HORIZONTAL_GRAVITY_MASK;
                int absLeft = mOverlayParams2.x;
                if (hGrav2 == Gravity.CENTER_HORIZONTAL) {
                    absLeft = (metrics.widthPixels / 2) + mOverlayParams2.x - (vw / 2);
                } else if (hGrav2 == Gravity.RIGHT) {
                    absLeft = metrics.widthPixels - mOverlayParams2.x - vw;
                }
                if (absLeft <= 0) { tl = 0; bl = 0; }
                if (absLeft + vw >= metrics.widthPixels) { tr = 0; br = 0; }

                GradientDrawable gd = new GradientDrawable(); gd.setColor(bgColor); gd.setCornerRadii(new float[]{tl, tl, tr, tr, br, br, bl, bl});
                mOverlayBgView2.setBackground(gd);

                if (o2Graph && graphHistory.size() > 1) { mGraphView2.setImageBitmap(graphBitmap); mGraphView2.invalidate(); } 
                else mGraphView2.setImageDrawable(null);
            } else mOverlayRoot2.postDelayed(updateOverlayBackground, 50); 
        }
    }
};

checkOverlayPermission() {
    AccessibilityService accService = tasker.getAccessibilityService();
    if (accService != null && Build.VERSION.SDK_INT >= 22) return true;
    if (Build.VERSION.SDK_INT >= 23 && !Settings.canDrawOverlays(context)) {
        intent = new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:" + context.getPackageName()));
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        context.startActivity(intent);
        return false;
    }
    return true;
}

initOverlay() {
    mainHandler.post(new Runnable() {
        run() {
            if ((mOverlayRoot1 != null || mOverlayRoot2 != null) || (!useO1 && !useO2) || !checkOverlayPermission()) return;

            AccessibilityService accService = tasker.getAccessibilityService();
            Context overlayContext = (accService != null) ? accService : context;
            mOverlayWindowManager = (WindowManager) overlayContext.getSystemService(context.WINDOW_SERVICE);

            int layoutFlag;
            if (accService != null && Build.VERSION.SDK_INT >= 22) layoutFlag = WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY;
            else layoutFlag = Build.VERSION.SDK_INT >= 26 ? WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY : WindowManager.LayoutParams.TYPE_PHONE;

            /* MEASURE VIEW: Event-Driven Fullscreen Detection */
            mMeasureView = new View(overlayContext);
            WindowManager.LayoutParams measureParams = new WindowManager.LayoutParams(
                WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT, layoutFlag, 
                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE | WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE, 
                PixelFormat.TRANSPARENT
            );

            if (Build.VERSION.SDK_INT >= 28) {
                measureParams.layoutInDisplayCutoutMode = WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;
            }

            mMeasureView.getViewTreeObserver().addOnGlobalLayoutListener(new ViewTreeObserver.OnGlobalLayoutListener() {
                onGlobalLayout() {
                    if (mMeasureView == null) return; 
                    Rect r = new Rect();
                    mMeasureView.getWindowVisibleDisplayFrame(r);
                    boolean isVis = (r.top > 0);
                    if (isStatusBarVisible.get() != isVis) {
                        isStatusBarVisible.set(isVis);
                    }
                }
            });
            try { mOverlayWindowManager.addView(mMeasureView, measureParams); } catch (Exception e) {}

