            if (!overlayClickTask && !overlayLongClickTask) touchFlags |= WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE;

            View.OnClickListener clickListener = null;
            if (overlayClickTask) {
                clickListener = new View.OnClickListener() { onClick(View v) { tasker.callTask("Network Speed Usage", new HashMap()); } };
            }
            View.OnLongClickListener longClickListener = null;
            if (overlayLongClickTask) {
                longClickListener = new View.OnLongClickListener() {
                    onLongClick(View v) { tasker.callTask("Network Speed Settings", new HashMap()); return true; }
