removeOverlay() {
    mainHandler.post(new Runnable() {
        run() {
            if (mOverlayWindowManager != null) {
                if (mMeasureView != null) { try { mOverlayWindowManager.removeView(mMeasureView); } catch(Exception e) {} }

                if (mOverlayRoot1 != null) { try { mOverlayWindowManager.removeView(mOverlayRoot1); } catch(Exception e) {} }
                if (mOverlayRoot2 != null) { try { mOverlayWindowManager.removeView(mOverlayRoot2); } catch(Exception e) {} }

                mMeasureView = null;
                mOverlayRoot1 = null; mOverlayView1 = null; mOverlayBgView1 = null; mGraphView1 = null; mOverlayParams1 = null;
                mIconDown1 = null; mTextDown1 = null; mIconUp1 = null; mTextUp1 = null; mIconTotal1 = null; mTextTotal1 = null;
                mIconMobile1 = null; mTextMobile1 = null; mIconWifi1 = null; mTextWifi1 = null; mIconFg1 = null; mTextFg1 = null;

                mOverlayRoot2 = null; mOverlayView2 = null; mOverlayBgView2 = null; mGraphView2 = null; mOverlayParams2 = null;
                mIconDown2 = null; mTextDown2 = null; mIconUp2 = null; mTextUp2 = null; mIconTotal2 = null; mTextTotal2 = null;
                mIconMobile2 = null; mTextMobile2 = null; mIconWifi2 = null; mTextWifi2 = null; mIconFg2 = null; mTextFg2 = null;

                mOverlayWindowManager = null;
            }
        }
    });
}

updateOverlayPosition1(int x, int y) {
    mainHandler.post(new Runnable() {
        run() {
            if (mOverlayRoot1 != null && mOverlayParams1 != null && mOverlayWindowManager != null) {
                DisplayMetrics metrics = new DisplayMetrics(); mOverlayWindowManager.getDefaultDisplay().getRealMetrics(metrics);
                int vw = mOverlayRoot1.getWidth(); int vh = mOverlayRoot1.getHeight();
                if (vw == 0) vw = 100; if (vh == 0) vh = 50;

                int newY = y; if (newY < 0) newY = 0; if (newY + vh > metrics.heightPixels) newY = metrics.heightPixels - vh;
                int newX = getAlignX(o1Align, x);
                if (o1Align == 0) { 
                    if (newX < 0) newX = 0; 
                    if (newX + vw > metrics.widthPixels) newX = metrics.widthPixels - vw; 
                } else if (o1Align == 4 || o1Align == 5) {
                    newX = mOverlayParams1.x; // Keep dynamic cutout X
                }

                mOverlayParams1.x = newX; mOverlayParams1.y = newY;
                mOverlayWindowManager.updateViewLayout(mOverlayRoot1, mOverlayParams1);
                mOverlayRoot1.post(updateOverlayBackground);
            }
        }
    });
}

updateOverlayPosition2(int x, int y) {
    mainHandler.post(new Runnable() {
        run() {
            if (mOverlayRoot2 != null && mOverlayParams2 != null && mOverlayWindowManager != null) {
                DisplayMetrics metrics = new DisplayMetrics(); mOverlayWindowManager.getDefaultDisplay().getRealMetrics(metrics);
                int vw = mOverlayRoot2.getWidth(); int vh = mOverlayRoot2.getHeight();
                if (vw == 0) vw = 100; if (vh == 0) vh = 50;

                int newY = y; if (newY < 0) newY = 0; if (newY + vh > metrics.heightPixels) newY = metrics.heightPixels - vh;
                int newX = getAlignX(o2Align, x);
                if (o2Align == 0) { 
                    if (newX < 0) newX = 0; 
                    if (newX + vw > metrics.widthPixels) newX = metrics.widthPixels - vw; 
                } else if (o2Align == 4 || o2Align == 5) {
                    newX = mOverlayParams2.x; // Keep dynamic cutout X
                }

                mOverlayParams2.x = newX; mOverlayParams2.y = newY;
                mOverlayWindowManager.updateViewLayout(mOverlayRoot2, mOverlayParams2);
                mOverlayRoot2.post(updateOverlayBackground);
            }
        }
    });
}

