apiMap = new HashMap();

apiMap.put("start", new Runnable() { run() { mainHandler.post(new Runnable() { run() { startMonitoring(); } }); } });
apiMap.put("stop", new Runnable() { run() { mainHandler.post(new Runnable() { run() { stopMonitoring(); } }); } });

apiMap.put("setPosition1", new Consumer() { accept(Object coordsObj) { int[] c = (int[]) coordsObj; if (o1Align == 0) manualO1X = c[0]; updateOverlayPosition1(c[0], c[1]); } });
apiMap.put("setPosition2", new Consumer() { accept(Object coordsObj) { int[] c = (int[]) coordsObj; if (o2Align == 0) manualO2X = c[0]; updateOverlayPosition2(c[0], c[1]); } });

apiMap.put("setAlign1", new Consumer() {
    accept(Object obj) { o1Align = ((Integer) obj).intValue(); 
        mainHandler.post(new Runnable() { run() { if (mOverlayRoot1 != null && mOverlayParams1 != null) {
            mOverlayParams1.gravity = getAlignGravity(o1Align);
            mOverlayParams1.x = getAlignX(o1Align, manualO1X);
            mOverlayWindowManager.updateViewLayout(mOverlayRoot1, mOverlayParams1); mOverlayRoot1.post(updateOverlayBackground);
        }}});
    }
});

apiMap.put("setAlign2", new Consumer() {
    accept(Object obj) { o2Align = ((Integer) obj).intValue(); 
        mainHandler.post(new Runnable() { run() { if (mOverlayRoot2 != null && mOverlayParams2 != null) {
            mOverlayParams2.gravity = getAlignGravity(o2Align);
            mOverlayParams2.x = getAlignX(o2Align, manualO2X);
            mOverlayWindowManager.updateViewLayout(mOverlayRoot2, mOverlayParams2); mOverlayRoot2.post(updateOverlayBackground);
        }}});
    }
});

apiMap.put("setPadding", new Consumer() { 
    accept(Object padsObj) { 
        int[] pads = (int[]) padsObj; padX = pads[0]; padY = pads[1];
        mainHandler.post(new Runnable() { run() {
            if (mOverlayView1 != null) mOverlayView1.setPadding(padX, padY, padX, padY);
            if (mOverlayView2 != null) mOverlayView2.setPadding(padX, padY, padX, padY);
        }});
    } 
});

apiMap.put("setBgRadius", new Consumer() { accept(Object radObj) { bgRadius = (Integer) radObj; mainHandler.post(updateOverlayBackground); } });

