apiMap.put("setTextSize", new Consumer() {
    accept(Object sizeObj) {
        overlayTextSizeInt = (Integer) sizeObj;
        mainHandler.post(new Runnable() {
            run() {
                int iconSize = (int) TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_SP, overlayTextSizeInt + 2, context.getResources().getDisplayMetrics());

                if (mOverlayView1 != null) {
                    if (mTextDown1 != null) mTextDown1.setTextSize(TypedValue.COMPLEX_UNIT_SP, overlayTextSizeInt);
