tasker.setJavaVariable("networkSpeedApi", apiMap);

/* ---------------- ENGINE LOGIC ---------------- */
formatSpeed(double speedBytesPerSec, boolean useShort) {
    unitLabel = useShort ? "B" : "B/s"; 
    units = new String[]{"", "k", "M", "G", "T"};
    valueFloat = (float)(speedBytesPerSec / 1000.0);
    unitIndex = 1;

    while (valueFloat >= 1000.0f && unitIndex < 4) { valueFloat /= 1000.0f; unitIndex++; }

    if (unitIndex >= 5) { value = "99+"; unit = units[4] + unitLabel; } 
    else {
        if (valueFloat >= 10.0f || unitIndex <= 1) value = String.valueOf(Math.round(valueFloat));
        else value = String.valueOf(Math.round(valueFloat * 10.0f) / 10.0d);
        unit = units[unitIndex] + unitLabel;
    }
    return new String[]{value, unit};
};

formatUsage(long bytes) {
    useBits = false; unitLabel = "B"; conversionFactor = 1024; units = new String[]{"", "K", "M", "G", "T"};
    valueFloat = (float)bytes; index = 0;
    while (valueFloat >= conversionFactor && index < units.length - 1) { valueFloat /= conversionFactor; index++; }

    if (index >= units.length) { value = "999+"; unit = units[units.length - 1] + unitLabel; } 
    else { value = String.valueOf(((int)(valueFloat * 100)) / 100.0f); unit = units[index] + unitLabel; }
    return value + " " + unit;
};

getDailyStartMillis(long timeInMillis) {
    Calendar cal = Calendar.getInstance();
    cal.setTimeInMillis(timeInMillis);
    cal.set(Calendar.HOUR_OF_DAY, 0); cal.set(Calendar.MINUTE, 0); cal.set(Calendar.SECOND, 0); cal.set(Calendar.MILLISECOND, 0);
    return cal.getTimeInMillis();
};

getCycleStartMillis(long timeInMillis) {
    Calendar cal = Calendar.getInstance(); cal.setTimeInMillis(timeInMillis);

    if (planType == 0) { // Monthly Plan
        int currentDay = cal.get(Calendar.DAY_OF_MONTH); int currentMax = cal.getActualMaximum(Calendar.DAY_OF_MONTH);
        int effectiveResetDay = monthlyResetDay;
        if (effectiveResetDay > currentMax) effectiveResetDay = currentMax;
        if (currentDay < effectiveResetDay) {
            cal.add(Calendar.MONTH, -1);
            int prevMax = cal.getActualMaximum(Calendar.DAY_OF_MONTH);
            effectiveResetDay = monthlyResetDay;
            if (effectiveResetDay > prevMax) effectiveResetDay = prevMax;
        }
        cal.set(Calendar.DAY_OF_MONTH, effectiveResetDay); cal.set(Calendar.HOUR_OF_DAY, 0); cal.set(Calendar.MINUTE, 0); cal.set(Calendar.SECOND, 0); cal.set(Calendar.MILLISECOND, 0);
        return cal.getTimeInMillis();
    } else { // Custom Plan
        long anchor = customCycleAnchor; if (timeInMillis < anchor) return anchor; 
        long cycleMs = customCycleDays * 24L * 60 * 60 * 1000L; long cyclesPassed = (timeInMillis - anchor) / cycleMs;
        return anchor + (cyclesPassed * cycleMs);
    }
};

mMobileCycleStartMillis = getCycleStartMillis(System.currentTimeMillis());
mWifiCycleStartMillis = getDailyStartMillis(System.currentTimeMillis());
mDailyStartMillis = getDailyStartMillis(System.currentTimeMillis());

updateForegroundAppUsage = new Runnable() {
    run() {
        if (lastFgPackage == null || lastFgPackage.isEmpty()) return;
        try {
            ApplicationInfo appInfo = context.getPackageManager().getApplicationInfo(lastFgPackage, 0);
            if (appInfo == null) return;
            int fgUid = appInfo.uid;

            long fgBytes = 0L; long fgEnd = System.currentTimeMillis();

            long startTime = ((o1Fg == 1) || (o2Fg == 1)) ? mMobileCycleStartMillis : mDailyStartMillis; 

            try {
                NetworkStats mStats = mNetworkStatsManager.querySummary(ConnectivityManager.TYPE_MOBILE, null, startTime, fgEnd);
                NetworkStats.Bucket b = new NetworkStats.Bucket();
                while(mStats.hasNextBucket()){ 
                    mStats.getNextBucket(b); 
                    if (b.getUid() == fgUid) fgBytes += b.getRxBytes() + b.getTxBytes(); 
                }
                mStats.close();
            } catch (Exception e) {}

            try {
                NetworkStats wStats = mNetworkStatsManager.querySummary(ConnectivityManager.TYPE_WIFI, null, startTime, fgEnd);
                NetworkStats.Bucket b = new NetworkStats.Bucket();
                while(wStats.hasNextBucket()){ 
                    wStats.getNextBucket(b); 
                    if (b.getUid() == fgUid) fgBytes += b.getRxBytes() + b.getTxBytes(); 
                }
                wStats.close();
            } catch (Exception e) {}

            lastFgUsageStr = formatUsage(fgBytes);

        } catch (Exception e) {}
    }
};

querySummaryForDevice() {
    try {
        if (mNetworkStatsManager == null) return;

        end = System.currentTimeMillis();
        long mobileCycleBytes = 0L; long mobileTodayBytes = 0L; long wifiBytes = 0L;

        NetworkStats.Bucket mobileCycleBucket = mNetworkStatsManager.querySummaryForDevice(ConnectivityManager.TYPE_MOBILE, null, mMobileCycleStartMillis, end);
        if (mobileCycleBucket != null) mobileCycleBytes = mobileCycleBucket.getRxBytes() + mobileCycleBucket.getTxBytes();

        NetworkStats.Bucket mobileTodayBucket = mNetworkStatsManager.querySummaryForDevice(ConnectivityManager.TYPE_MOBILE, null, mDailyStartMillis, end);
        if (mobileTodayBucket != null) mobileTodayBytes = mobileTodayBucket.getRxBytes() + mobileTodayBucket.getTxBytes();

        NetworkStats.Bucket wifiBucket = mNetworkStatsManager.querySummaryForDevice(ConnectivityManager.TYPE_WIFI, null, mDailyStartMillis, end);
        if (wifiBucket != null) wifiBytes = wifiBucket.getRxBytes() + wifiBucket.getTxBytes();

        lastMobileCycleUsageStr = formatUsage(mobileCycleBytes); 
        lastMobileTodayUsageStr = formatUsage(mobileTodayBytes); 
        lastWifiUsageStr = formatUsage(wifiBytes);

        // Quota Logic
        quotaState = 0;
        if (dataLimitMb > 0 && mobileCycleBytes > 0) {
            double limitBytes = dataLimitMb * 1024.0 * 1024.0;
            double pct = mobileCycleBytes / limitBytes;
            if (pct >= 0.90) quotaState = 2; else if (pct >= 0.80) quotaState = 1;
        }
    } catch (Exception e) {}
};

querySummaryForDevice();

rebuildInterfaceList() {
    synchronized (mSyncLock) {
        mInterfaceList.clear(); linkProperties = mLinkPropertiesMap.values(); lpIterator = linkProperties.iterator();
        while (lpIterator.hasNext()) {
            link = (LinkProperties) lpIterator.next(); iface = link.getInterfaceName();
            if (iface != null) { mInterfaceList.add(iface); mInterfaceList.add(CLAT_PREFIX + iface); }
        }
    }
};

getInterfaceTrafficStats() {
    totalRx = 0L; totalTx = 0L;
    synchronized (mSyncLock) {
        if (mInterfaceList.size() == 0) return new long[]{totalRx, totalTx};
        for (int i = 0; i < mInterfaceList.size(); i++) {
            try {
                iface = (String) mInterfaceList.get(i);
                rx = TrafficStats.getRxBytes(iface); tx = TrafficStats.getTxBytes(iface);
                if (rx != TrafficStats.UNSUPPORTED && tx != TrafficStats.UNSUPPORTED) { totalRx += rx; totalTx += tx; }
            } catch (Exception e) {}
        }
    }
    return new long[]{totalRx, totalTx};
};

cm = (ConnectivityManager) context.getSystemService(context.CONNECTIVITY_SERVICE);
km = (KeyguardManager) context.getSystemService(context.KEYGUARD_SERVICE);

lastTx = 0L; lastRx = 0L;
lastTime = SystemClock.elapsedRealtime();
counter = 0;

updateSpeedRunnable = new Runnable() {
    run() {
        if (!isRunning.get() || (!useO1 && !useO2 && !useNotification)) return;
        try {
            now = SystemClock.elapsedRealtime();
            stats = getInterfaceTrafficStats();
            rx = stats[0]; tx = stats[1];
            dt = now - lastTime;

            txBps = 0.0; rxBps = 0.0;
            if (!mNetworksChanged && dt > 0 && lastTx > 0 && lastRx > 0) {
                txBps = (tx - lastTx) * 1000.0 / dt;
                rxBps = (rx - lastRx) * 1000.0 / dt;
            } else if (mNetworksChanged) mNetworksChanged = false;

            total = txBps + rxBps;
            if (total == 0) zeroSpeedTicks++; else zeroSpeedTicks = 0;

            if ((useO1 && o1Graph) || (useO2 && o2Graph)) {
                graphHistory.add(new Float(total)); if (graphHistory.size() > 30) graphHistory.remove(0);
            }

            boolean needsUsage = (useO1 && (o1Mob > 0 || o1Wifi || o1Fg > 0)) || 
                                 (useO2 && (o2Mob > 0 || o2Wifi || o2Fg > 0)) || 
                                 (useNotification && (notifMobileMode > 0 || notifShowWifi));
            if (needsUsage && counter == 0) querySummaryForDevice();

            boolean needsFg = (useO1 && o1Fg > 0) || (useO2 && o2Fg > 0);
            if (needsFg) {
                try {
                    android.app.usage.UsageStatsManager usm = (android.app.usage.UsageStatsManager) context.getSystemService(Context.USAGE_STATS_SERVICE);
                    long time = System.currentTimeMillis();
                    android.app.usage.UsageEvents events = usm.queryEvents(time - UPDATE_INTERVAL_MS - 500, time);
                    boolean changed = false; android.app.usage.UsageEvents.Event ev = new android.app.usage.UsageEvents.Event();
                    while (events.hasNextEvent()) {
                        events.getNextEvent(ev);
                        if (ev.getEventType() == 1) { lastFgPackage = ev.getPackageName(); changed = true; }
                    }
                    if (changed || counter == 0) updateForegroundAppUsage.run();
                } catch (Exception e) {}
            }

            boolean isMobileActive = false; boolean isWifiActive = false;
            try {
                Network activeNet = cm.getActiveNetwork();
                if (activeNet != null) {
                    NetworkCapabilities caps = cm.getNetworkCapabilities(activeNet);
                    if (caps != null) {
                        isWifiActive = caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI);
                        isMobileActive = caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR);
                    }
                }
            } catch(Exception e) {}

            boolean effNotifMob = (notifMobileMode > 0) && (!notifActiveOnly || isMobileActive);
            boolean effNotifWifi = notifShowWifi && (!notifActiveOnly || isWifiActive);

            boolean isLocked = km.isKeyguardLocked();
            boolean isFullscreen = !isStatusBarVisible.get();
            boolean autoHidden = overlayAutoHide && (zeroSpeedTicks * UPDATE_INTERVAL_MS >= 3000);
            boolean shouldHide = (hideOverlayInFullscreen && isFullscreen) || (hideOverlayInLockscreen && isLocked) || autoHidden;

            // Helper to determine active Colors
            int cDown = Color.WHITE; if (useCustomColors) try{ cDown = Color.parseColor(colorDownStr); }catch(Exception e){}
            int cUp = Color.WHITE; if (useCustomColors) try{ cUp = Color.parseColor(colorUpStr); }catch(Exception e){}
            int cTotal = Color.WHITE; if (useCustomColors) try{ cTotal = Color.parseColor(colorTotalStr); }catch(Exception e){}
            int cMobile = Color.WHITE; if (useCustomColors) try{ cMobile = Color.parseColor(colorMobileStr); }catch(Exception e){}
            int cWifi = Color.WHITE; if (useCustomColors) try{ cWifi = Color.parseColor(colorWifiStr); }catch(Exception e){}
            int cFgApp = Color.WHITE; if (useCustomColors) try{ cFgApp = Color.parseColor(colorFgAppStr); }catch(Exception e){}

            if (quotaState == 2) {
                int cred = Color.parseColor("#FFF44336"); if (useCustomColors) try { cred = Color.parseColor(colorCritStr); } catch(Exception e){}
                cDown = cred; cUp = cred; cTotal = cred; cMobile = cred; cWifi = cred; cFgApp = cred;
            } else if (quotaState == 1) {
                int cwarn = Color.parseColor("#FFFF9800"); if (useCustomColors) try { cwarn = Color.parseColor(colorWarnStr); } catch(Exception e){}
                cDown = cwarn; cUp = cwarn; cTotal = cwarn; cMobile = cwarn; cWifi = cwarn; cFgApp = cwarn;
            }

            downParts = formatSpeed(rxBps, shortUnits);
            upParts = formatSpeed(txBps, shortUnits);
            totalParts = formatSpeed(total, shortUnits);

            if (!lastFgPackage.equals(prevFgPackage)) {
                try { lastFgIconDrawable = context.getPackageManager().getApplicationIcon(lastFgPackage); } catch (Exception e) { lastFgIconDrawable = null; }
                prevFgPackage = lastFgPackage;
            }

            /* 1. OVERLAY 1 LOGIC */
            if (useO1 && mOverlayView1 != null && mOverlayRoot1 != null) {
                if (shouldHide) {
                    if (mOverlayRoot1.getVisibility() == View.VISIBLE) mOverlayRoot1.setVisibility(View.GONE);
                } else {
                    if (mOverlayRoot1.getVisibility() == View.GONE) mOverlayRoot1.setVisibility(View.VISIBLE);

                    boolean effO1Mob = (o1Mob > 0) && (!overlayActiveOnly || isMobileActive);
                    boolean effO1Wifi = o1Wifi && (!overlayActiveOnly || isWifiActive);
                    boolean effO1Fg = o1Fg > 0 && lastFgPackage != null && !lastFgPackage.isEmpty();

                    int lastType = 0; 
                    if (o1Speed) lastType = 1; if (effO1Mob) lastType = 2; if (effO1Wifi) lastType = 3; if (effO1Fg) lastType = 4;

                    if (o1Speed) {
                        if (o1Sep) {
                            mIconDown1.setVisibility(View.VISIBLE); mTextDown1.setVisibility(View.VISIBLE); mIconDown1.setColorFilter(cDown, PorterDuff.Mode.SRC_IN); mTextDown1.setTextColor(cDown);
                            mIconUp1.setVisibility(View.VISIBLE); mTextUp1.setVisibility(View.VISIBLE); mIconUp1.setColorFilter(cUp, PorterDuff.Mode.SRC_IN); mTextUp1.setTextColor(cUp);
                            mIconTotal1.setVisibility(View.GONE); mTextTotal1.setVisibility(View.GONE);

                            LinearLayout.LayoutParams lpDown = (LinearLayout.LayoutParams) mTextDown1.getLayoutParams(); lpDown.leftMargin=0; lpDown.rightMargin = 25; mTextDown1.setLayoutParams(lpDown);
                            LinearLayout.LayoutParams lpUp = (LinearLayout.LayoutParams) mTextUp1.getLayoutParams(); lpUp.leftMargin=0; lpUp.rightMargin = (lastType == 1) ? 0 : 25; mTextUp1.setLayoutParams(lpUp);
                            mTextDown1.setText(downParts[0] + downParts[1]); mTextUp1.setText(upParts[0] + upParts[1]);
                        } else {
                            mIconTotal1.setVisibility(View.VISIBLE); mTextTotal1.setVisibility(View.VISIBLE); mIconTotal1.setColorFilter(cTotal, PorterDuff.Mode.SRC_IN); mTextTotal1.setTextColor(cTotal);
                            mIconDown1.setVisibility(View.GONE); mTextDown1.setVisibility(View.GONE); mIconUp1.setVisibility(View.GONE); mTextUp1.setVisibility(View.GONE);

                            LinearLayout.LayoutParams lpTot = (LinearLayout.LayoutParams) mTextTotal1.getLayoutParams(); lpTot.leftMargin=0; lpTot.rightMargin = (lastType == 1) ? 0 : 25; mTextTotal1.setLayoutParams(lpTot);
                            mTextTotal1.setText(totalParts[0] + totalParts[1]);
                        }
                    } else {
                        mIconDown1.setVisibility(View.GONE); mTextDown1.setVisibility(View.GONE); mIconUp1.setVisibility(View.GONE); mTextUp1.setVisibility(View.GONE); mIconTotal1.setVisibility(View.GONE); mTextTotal1.setVisibility(View.GONE);
                    }

                    if (effO1Mob) {
                        mIconMobile1.setVisibility(View.VISIBLE); mTextMobile1.setVisibility(View.VISIBLE); mIconMobile1.setColorFilter(cMobile, PorterDuff.Mode.SRC_IN); mTextMobile1.setTextColor(cMobile);
                        LinearLayout.LayoutParams lpMob = (LinearLayout.LayoutParams) mTextMobile1.getLayoutParams(); lpMob.leftMargin=0; lpMob.rightMargin = (lastType == 2) ? 0 : 25; mTextMobile1.setLayoutParams(lpMob);
                        mTextMobile1.setText(o1Mob == 2 ? lastMobileTodayUsageStr : lastMobileCycleUsageStr);
                    } else { mIconMobile1.setVisibility(View.GONE); mTextMobile1.setVisibility(View.GONE); }

                    if (effO1Wifi) {
                        mIconWifi1.setVisibility(View.VISIBLE); mTextWifi1.setVisibility(View.VISIBLE); mIconWifi1.setColorFilter(cWifi, PorterDuff.Mode.SRC_IN); mTextWifi1.setTextColor(cWifi);
                        LinearLayout.LayoutParams lpWifi = (LinearLayout.LayoutParams) mTextWifi1.getLayoutParams(); lpWifi.leftMargin=0; lpWifi.rightMargin = (lastType == 3) ? 0 : 25; mTextWifi1.setLayoutParams(lpWifi);
                        mTextWifi1.setText(lastWifiUsageStr);
                    } else { mIconWifi1.setVisibility(View.GONE); mTextWifi1.setVisibility(View.GONE); }

                    if (effO1Fg) {
                        mIconFg1.setVisibility(View.VISIBLE); mTextFg1.setVisibility(View.VISIBLE);
                        if (lastFgIconDrawable != null) { mIconFg1.setImageDrawable(lastFgIconDrawable); mIconFg1.clearColorFilter(); }
                        else { mIconFg1.setImageDrawable(context.getDrawable(android.R.drawable.sym_def_app_icon)); mIconFg1.setColorFilter(cFgApp, PorterDuff.Mode.SRC_IN); }
                        mTextFg1.setTextColor(cFgApp);
                        LinearLayout.LayoutParams lpFg = (LinearLayout.LayoutParams) mTextFg1.getLayoutParams(); lpFg.leftMargin=0; lpFg.rightMargin = (lastType == 4) ? 0 : 25; mTextFg1.setLayoutParams(lpFg);
                        mTextFg1.setText(lastFgUsageStr);
                    } else { mIconFg1.setVisibility(View.GONE); mTextFg1.setVisibility(View.GONE); }
                }
            }

            /* 2. OVERLAY 2 LOGIC */
            if (useO2 && mOverlayView2 != null && mOverlayRoot2 != null) {
                if (shouldHide) {
                    if (mOverlayRoot2.getVisibility() == View.VISIBLE) mOverlayRoot2.setVisibility(View.GONE);
                } else {
                    if (mOverlayRoot2.getVisibility() == View.GONE) mOverlayRoot2.setVisibility(View.VISIBLE);

                    boolean effO2Mob = (o2Mob > 0) && (!overlayActiveOnly || isMobileActive);
                    boolean effO2Wifi = o2Wifi && (!overlayActiveOnly || isWifiActive);
                    boolean effO2Fg = o2Fg > 0 && lastFgPackage != null && !lastFgPackage.isEmpty();

                    int lastType = 0; 
                    if (o2Speed) lastType = 1; if (effO2Mob) lastType = 2; if (effO2Wifi) lastType = 3; if (effO2Fg) lastType = 4;

                    if (o2Speed) {
                        if (o2Sep) {
                            mIconDown2.setVisibility(View.VISIBLE); mTextDown2.setVisibility(View.VISIBLE); mIconDown2.setColorFilter(cDown, PorterDuff.Mode.SRC_IN); mTextDown2.setTextColor(cDown);
                            mIconUp2.setVisibility(View.VISIBLE); mTextUp2.setVisibility(View.VISIBLE); mIconUp2.setColorFilter(cUp, PorterDuff.Mode.SRC_IN); mTextUp2.setTextColor(cUp);
                            mIconTotal2.setVisibility(View.GONE); mTextTotal2.setVisibility(View.GONE);

                            LinearLayout.LayoutParams lpDown = (LinearLayout.LayoutParams) mTextDown2.getLayoutParams(); lpDown.leftMargin=0; lpDown.rightMargin = 25; mTextDown2.setLayoutParams(lpDown);
                            LinearLayout.LayoutParams lpUp = (LinearLayout.LayoutParams) mTextUp2.getLayoutParams(); lpUp.leftMargin=0; lpUp.rightMargin = (lastType == 1) ? 0 : 25; mTextUp2.setLayoutParams(lpUp);
                            mTextDown2.setText(downParts[0] + downParts[1]); mTextUp2.setText(upParts[0] + upParts[1]);
                        } else {
                            mIconTotal2.setVisibility(View.VISIBLE); mTextTotal2.setVisibility(View.VISIBLE); mIconTotal2.setColorFilter(cTotal, PorterDuff.Mode.SRC_IN); mTextTotal2.setTextColor(cTotal);
                            mIconDown2.setVisibility(View.GONE); mTextDown2.setVisibility(View.GONE); mIconUp2.setVisibility(View.GONE); mTextUp2.setVisibility(View.GONE);

                            LinearLayout.LayoutParams lpTot = (LinearLayout.LayoutParams) mTextTotal2.getLayoutParams(); lpTot.leftMargin=0; lpTot.rightMargin = (lastType == 1) ? 0 : 25; mTextTotal2.setLayoutParams(lpTot);
                            mTextTotal2.setText(totalParts[0] + totalParts[1]);
                        }
                    } else {
                        mIconDown2.setVisibility(View.GONE); mTextDown2.setVisibility(View.GONE); mIconUp2.setVisibility(View.GONE); mTextUp2.setVisibility(View.GONE); mIconTotal2.setVisibility(View.GONE); mTextTotal2.setVisibility(View.GONE);
                    }

                    if (effO2Mob) {
                        mIconMobile2.setVisibility(View.VISIBLE); mTextMobile2.setVisibility(View.VISIBLE); mIconMobile2.setColorFilter(cMobile, PorterDuff.Mode.SRC_IN); mTextMobile2.setTextColor(cMobile);
                        LinearLayout.LayoutParams lpMob = (LinearLayout.LayoutParams) mTextMobile2.getLayoutParams(); lpMob.leftMargin=0; lpMob.rightMargin = (lastType == 2) ? 0 : 25; mTextMobile2.setLayoutParams(lpMob);
                        mTextMobile2.setText(o2Mob == 2 ? lastMobileTodayUsageStr : lastMobileCycleUsageStr);
                    } else { mIconMobile2.setVisibility(View.GONE); mTextMobile2.setVisibility(View.GONE); }

                    if (effO2Wifi) {
                        mIconWifi2.setVisibility(View.VISIBLE); mTextWifi2.setVisibility(View.VISIBLE); mIconWifi2.setColorFilter(cWifi, PorterDuff.Mode.SRC_IN); mTextWifi2.setTextColor(cWifi);
                        LinearLayout.LayoutParams lpWifi = (LinearLayout.LayoutParams) mTextWifi2.getLayoutParams(); lpWifi.leftMargin=0; lpWifi.rightMargin = (lastType == 3) ? 0 : 25; mTextWifi2.setLayoutParams(lpWifi);
                        mTextWifi2.setText(lastWifiUsageStr);
                    } else { mIconWifi2.setVisibility(View.GONE); mTextWifi2.setVisibility(View.GONE); }

                    if (effO2Fg) {
                        mIconFg2.setVisibility(View.VISIBLE); mTextFg2.setVisibility(View.VISIBLE);
                        if (lastFgIconDrawable != null) { mIconFg2.setImageDrawable(lastFgIconDrawable); mIconFg2.clearColorFilter(); }
                        else { mIconFg2.setImageDrawable(context.getDrawable(android.R.drawable.sym_def_app_icon)); mIconFg2.setColorFilter(cFgApp, PorterDuff.Mode.SRC_IN); }
                        mTextFg2.setTextColor(cFgApp);
                        LinearLayout.LayoutParams lpFg = (LinearLayout.LayoutParams) mTextFg2.getLayoutParams(); lpFg.leftMargin=0; lpFg.rightMargin = (lastType == 4) ? 0 : 25; mTextFg2.setLayoutParams(lpFg);
                        mTextFg2.setText(lastFgUsageStr);
                    } else { mIconFg2.setVisibility(View.GONE); mTextFg2.setVisibility(View.GONE); }
                }
            }

            if (useO1 || useO2) mOverlayRoot1.post(updateOverlayBackground);

            /* 3. NOTIFICATION LOGIC */
            if (useNotification) {
                downP = formatSpeed(rxBps, false); upP = formatSpeed(txBps, false);
                speedText = "Down: " + downP[0] + " " + downP[1] + "   Up: " + upP[0] + " " + upP[1];
                iconParts = formatSpeed(total, false);
                icon = getIndicatorIcon(iconParts[0], iconParts[1]);

                String notifUsageStr = "";
                if (effNotifMob) notifUsageStr += "Mobile: " + (notifMobileMode == 2 ? lastMobileTodayUsageStr : lastMobileCycleUsageStr) + "   ";
                if (effNotifWifi) notifUsageStr += "WiFi: " + lastWifiUsageStr;
                notifUsageStr = notifUsageStr.trim();

                boolean hasNotifUsage = !notifUsageStr.isEmpty();

                if (hasNotifUsage) { mNotificationBuilder.setContentTitle(notifUsageStr); if (showDownUpSpeed) mNotificationBuilder.setContentText(speedText); else mNotificationBuilder.setContentText(null); } 
                else { if (showDownUpSpeed) mNotificationBuilder.setContentTitle(speedText); else mNotificationBuilder.setContentTitle("Network Speed Monitor"); mNotificationBuilder.setContentText(null); }

                mNotificationBuilder.setSmallIcon(icon);
                if (Build.VERSION.SDK_INT >= 20) {
                    mSummaryNotificationBuilder.setSmallIcon(icon);
                    mNotificationManager.notify(SUMMARY_NOTIFICATION_ID, mSummaryNotificationBuilder.build());
                }
                mNotificationManager.notify(NOTIFICATION_ID, mNotificationBuilder.build());
            }

            lastTx = tx; lastRx = rx; lastTime = now;

            int loopMax = 30000 / UPDATE_INTERVAL_MS; if (loopMax < 1) loopMax = 1; counter = (counter + 1) % loopMax;
            if (isRunning.get()) mainHandler.postDelayed(updateSpeedRunnable, UPDATE_INTERVAL_MS);

        } catch (Exception e) {
            logToFile("Error in update loop: " + e.getMessage());
            if (isRunning.get()) mainHandler.postDelayed(updateSpeedRunnable, UPDATE_INTERVAL_MS);
        }
    }
};

startMonitoring() {
    if (!useO1 && !useO2 && !useNotification) {
        stopMonitoring();
        return;
    }
    lastTx = 0L; lastRx = 0L; lastTime = SystemClock.elapsedRealtime(); counter = 0;
    mainHandler.removeCallbacks(updateSpeedRunnable);
    if (useO1 || useO2) initOverlay();
    if (isRunning.get()) mainHandler.post(updateSpeedRunnable);
};

stopMonitoring() {
    mainHandler.removeCallbacks(updateSpeedRunnable);
    mNotificationManager.cancel(NOTIFICATION_ID);
    mNotificationManager.cancel(SUMMARY_NOTIFICATION_ID);
    removeOverlay();
};

networkRequest = new NetworkRequest.Builder().addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET).addCapability(NetworkCapabilities.NET_CAPABILITY_NOT_VPN).build();

networkCallback = tasker.implementClass(ConnectivityManager.NetworkCallback.class, new ClassImplementation(){
    run(Callable superCaller, String methodName, Object[] args){
        if (methodName.equals("onLinkPropertiesChanged")) {
            network = (Network) args[0]; linkProperties = (LinkProperties) args[1];
            synchronized (mSyncLock) { mNetworksChanged = true; mLinkPropertiesMap.put(network, linkProperties); rebuildInterfaceList(); }
            return null;
        }
        if (methodName.equals("onAvailable")) {
            network = (Network) args[0];
            synchronized (mSyncLock) {
                try { linkProperties = cm.getLinkProperties(network); if (linkProperties != null) { mLinkPropertiesMap.put(network, linkProperties); rebuildInterfaceList(); } } catch (Exception e) {}
                mNetworksChanged = true;
            }
            startMonitoring(); // Always start on network available
            return null;
        }
        if (methodName.equals("onLost")) {
            network = (Network) args[0];
            synchronized (mSyncLock) { mNetworksChanged = true; mLinkPropertiesMap.remove(network); rebuildInterfaceList(); }
            if (mLinkPropertiesMap.isEmpty()) stopMonitoring();
            return null;
        }
        return superCaller.call();
    }
});

broadcastReceiver = tasker.implementClass(BroadcastReceiver.class, new ClassImplementation(){
    run(Callable superCaller, String methodName, Object[] args){
        if (!methodName.equals("onReceive")) return superCaller.call();

        action = ((Intent) args[1]).getAction();

        if (Intent.ACTION_SCREEN_OFF.equals(action)) {
            stopMonitoring(); // Save battery when screen is completely off
        } else if (Intent.ACTION_SCREEN_ON.equals(action) || Intent.ACTION_USER_PRESENT.equals(action)) {
            if (cm.getActiveNetwork() != null) startMonitoring(); // Resume on screen wake
        } else if (Intent.ACTION_DATE_CHANGED.equals(action) || Intent.ACTION_TIME_CHANGED.equals(action)) {
            mMobileCycleStartMillis = getCycleStartMillis(System.currentTimeMillis()); mWifiCycleStartMillis = getDailyStartMillis(System.currentTimeMillis()); mDailyStartMillis = getDailyStartMillis(System.currentTimeMillis());
        } else if ("network.speed.usage".equals(action)) {
            vars = new HashMap(); tasker.callTask("Network Speed Usage", vars); logToFile("ACTION: Notification tapped, starting 'Network Speed Usage' task");
        }
        return null;
    }
});

cm.registerNetworkCallback(networkRequest, networkCallback);
intentFilter = new IntentFilter(); intentFilter.addAction(Intent.ACTION_SCREEN_ON); intentFilter.addAction(Intent.ACTION_SCREEN_OFF); intentFilter.addAction(Intent.ACTION_USER_PRESENT); intentFilter.addAction(Intent.ACTION_DATE_CHANGED); intentFilter.addAction(Intent.ACTION_TIME_CHANGED); intentFilter.addAction("network.speed.usage");

if (Build.VERSION.SDK_INT >= 33) { context.getApplicationContext().registerReceiver(broadcastReceiver, intentFilter, 4); } 
else { context.getApplicationContext().registerReceiver(broadcastReceiver, intentFilter); }

cleanupAction = new Action() {
  run() {
    isRunning.set(false);
    try { mainHandler.removeCallbacksAndMessages(null); } catch (Exception e) {}
    try { cm.unregisterNetworkCallback(networkCallback); } catch (Exception e) {}
    try { context.getApplicationContext().unregisterReceiver(broadcastReceiver); } catch (Exception e) {}
    try { mNotificationManager.cancel(NOTIFICATION_ID); } catch (Exception e) {}
    try { mNotificationManager.cancel(SUMMARY_NOTIFICATION_ID); } catch (Exception e) {}
    try { removeOverlay(); } catch (Exception e) {}
    try { if (mIconBitmap != null && !mIconBitmap.isRecycled()) mIconBitmap.recycle(); } catch (Exception e) {}
    try { if (graphBitmap != null && !graphBitmap.isRecycled()) graphBitmap.recycle(); } catch (Exception e) {}

    tasker.setJavaVariable("networkSpeedApi", null); tasker.setJavaVariable("networkSpeedStop", null);
    logToFile("--- ENGINE STOPPED ---");
  }
};
stopSignal.subscribe(cleanupAction);

if (networkSpeedApi == null || networkSpeedApi == void) {
    return false;
}
return true;

