        Consumer showColorPicker = new Consumer() {
            accept(Object[] args) {
                String labelStr = (String) args[0]; int index = ((Integer) args[1]).intValue(); String apiCommand = (String) args[2];
                TextView hexDisplay = (TextView) args[3]; View colorPreview = (View) args[4];
                String defaultHex = (index == 0) ? "#88000000" : (index == 7 ? "#FFFF9800" : (index == 8 ? "#FFF44336" : (index == 9 ? "#90FFFFFF" : "#FFFFFFFF")));
                int startColor = Color.parseColor(defaultHex); try { startColor = Color.parseColor(liveColors[index]); } catch(Exception e){}
                int[] alpha = new int[] { Color.alpha(startColor) }; float[] hsv = new float[3]; Color.colorToHSV(startColor, hsv);
                AlertDialog.Builder cpBuilder = new AlertDialog.Builder(activity, themeResId); cpBuilder.setTitle(labelStr);
                ScrollView cpScroll = new ScrollView(dialogContext); LinearLayout cpLayout = new LinearLayout(dialogContext); cpLayout.setOrientation(LinearLayout.VERTICAL); cpLayout.setPadding(50, 50, 50, 50);
                LinearLayout topRow = new LinearLayout(dialogContext); topRow.setOrientation(LinearLayout.HORIZONTAL); topRow.setGravity(Gravity.CENTER);
                int boxSize = (int)(220 * metrics.density); int hueWidth = (int)(30 * metrics.density);
                FrameLayout svContainer = new FrameLayout(dialogContext); svContainer.setLayoutParams(new LinearLayout.LayoutParams(boxSize, boxSize));
                View svView = new View(dialogContext); svView.setLayoutParams(new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
                View svCursor = new View(dialogContext); int cursorSize = (int)(16 * metrics.density); FrameLayout.LayoutParams cursorParams = new FrameLayout.LayoutParams(cursorSize, cursorSize);
                GradientDrawable cursorBg = new GradientDrawable(); cursorBg.setShape(GradientDrawable.OVAL); cursorBg.setStroke((int)(2 * metrics.density), Color.WHITE);
                GradientDrawable inner = new GradientDrawable(); inner.setShape(GradientDrawable.OVAL); inner.setStroke((int)(1 * metrics.density), Color.BLACK);
                LayerDrawable cursorLd = new LayerDrawable(new Drawable[]{cursorBg, inner}); svCursor.setBackground(cursorLd);
                svContainer.addView(svView); svContainer.addView(svCursor);
                View hueView = new View(dialogContext); LinearLayout.LayoutParams hueParams = new LinearLayout.LayoutParams(hueWidth, boxSize); hueParams.leftMargin = 40; hueView.setLayoutParams(hueParams);
                int[] hueColors = new int[] { 0xFFFF0000, 0xFFFF00FF, 0xFF0000FF, 0xFF00FFFF, 0xFF00FF00, 0xFFFFFF00, 0xFFFF0000 };
                GradientDrawable hueDrawable = new GradientDrawable(GradientDrawable.Orientation.BOTTOM_TOP, hueColors); hueView.setBackground(hueDrawable);
                topRow.addView(svContainer); topRow.addView(hueView); cpLayout.addView(topRow);
                TextView alphaLabel = new TextView(dialogContext); alphaLabel.setText("Alpha (Transparency)"); alphaLabel.setTextColor(textPrimary); alphaLabel.setPadding(0, 40, 0, 10); cpLayout.addView(alphaLabel);
                SeekBar alphaBar = new SeekBar(dialogContext); alphaBar.setMax(255); alphaBar.setProgress(alpha[0]); cpLayout.addView(alphaBar);
                LinearLayout bottomRow = new LinearLayout(dialogContext); bottomRow.setOrientation(LinearLayout.HORIZONTAL); bottomRow.setGravity(Gravity.CENTER_VERTICAL); bottomRow.setPadding(0, 40, 0, 0);
                TextView hexLabel = new TextView(dialogContext); hexLabel.setText("Hex:  "); hexLabel.setTextColor(textPrimary); bottomRow.addView(hexLabel);
                EditText hexInput = new EditText(dialogContext); hexInput.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.0f)); hexInput.setTextColor(textPrimary); bottomRow.addView(hexInput);
                View exampleBox = new View(dialogContext); LinearLayout.LayoutParams exParams = new LinearLayout.LayoutParams((int)(40*metrics.density), (int)(40*metrics.density)); exParams.leftMargin = 40; exampleBox.setLayoutParams(exParams);
                FrameLayout previewContainer = new FrameLayout(dialogContext); previewContainer.setPadding(3,3,3,3); previewContainer.setBackgroundColor(isDark ? Color.WHITE : Color.BLACK); previewContainer.addView(exampleBox); bottomRow.addView(previewContainer);
                cpLayout.addView(bottomRow); cpScroll.addView(cpLayout);

                Runnable updateViews = new Runnable() {
                    run() {
                        int pureColor = Color.HSVToColor(new float[]{hsv[0], 1f, 1f});
                        GradientDrawable base = new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT, new int[]{0xFFFFFFFF, pureColor});
                        GradientDrawable shade = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{0x00000000, 0xFF000000});
                        LayerDrawable ld = new LayerDrawable(new Drawable[]{base, shade}); svView.setBackground(ld);
                        cursorParams.leftMargin = (int) (hsv[1] * boxSize) - (cursorSize / 2); cursorParams.topMargin = (int) ((1f - hsv[2]) * boxSize) - (cursorSize / 2); svCursor.setLayoutParams(cursorParams);
                        int c = Color.HSVToColor(alpha[0], hsv); exampleBox.setBackgroundColor(c);
                        String hexStr = String.format("#%08X", c).toUpperCase(); if (!hexInput.hasFocus()) hexInput.setText(hexStr);
                    }
                };
                svView.setOnTouchListener(new View.OnTouchListener() { onTouch(View v, MotionEvent event) { float x = event.getX(); float y = event.getY(); if (x < 0) x = 0; if (x > boxSize) x = boxSize; if (y < 0) y = 0; if (y > boxSize) y = boxSize; hsv[1] = x / boxSize; hsv[2] = 1f - (y / boxSize); updateViews.run(); return true; } });
                hueView.setOnTouchListener(new View.OnTouchListener() { onTouch(View v, MotionEvent event) { float y = event.getY(); if (y < 0) y = 0; if (y > boxSize) y = boxSize; hsv[0] = 360f - ((y / boxSize) * 360f); updateViews.run(); return true; } });
                alphaBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() { onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) { if (fromUser) { alpha[0] = progress; updateViews.run(); } } onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {} });
                hexInput.addTextChangedListener(new TextWatcher() { beforeTextChanged(CharSequence s, int start, int count, int after) {} onTextChanged(CharSequence s, int start, int before, int count) {} afterTextChanged(Editable s) { if (hexInput.hasFocus()) { try { String hex = s.toString().trim(); if (!hex.startsWith("#")) hex = "#" + hex; int c = Color.parseColor(hex); alpha[0] = Color.alpha(c); Color.colorToHSV(c, hsv); alphaBar.setProgress(alpha[0]); updateViews.run(); } catch (Exception e) {} } } });
                updateViews.run();

                cpBuilder.setView(cpScroll);
                cpBuilder.setPositiveButton("Set", new DialogInterface.OnClickListener() {
                    onClick(DialogInterface dialog, int which) {
                        int finalC = Color.HSVToColor(alpha[0], hsv); String finalHex = String.format("#%08X", finalC).toUpperCase();
                        liveColors[index] = finalHex; hexDisplay.setText(finalHex); colorPreview.setBackgroundColor(finalC); networkSpeedApi.get(apiCommand).accept(finalHex);
                    }
                });
                cpBuilder.setNeutralButton("Default", new DialogInterface.OnClickListener() {
                    onClick(DialogInterface dialog, int which) {
                        liveColors[index] = defaultHex; hexDisplay.setText(defaultHex); try { colorPreview.setBackgroundColor(Color.parseColor(defaultHex)); } catch(Exception e){} networkSpeedApi.get(apiCommand).accept(defaultHex);
                    }
                });
                cpBuilder.setNegativeButton("Cancel", null); cpBuilder.show();
            }
        };

