        Switch swO2Sep = new Switch(dialogContext); swO2Sep.setText("Separate Format (Down/Up)"); swO2Sep.setChecked(o2Sep); swO2Sep.setEnabled(o2Speed); swO2Sep.setPadding(0, 0, 0, 30); layout4.addView(swO2Sep);
        swO2Speed.setOnClickListener(new View.OnClickListener() { onClick(View v) { swO2Sep.setEnabled(swO2Speed.isChecked()); } });

        Switch swO2Graph = new Switch(dialogContext); swO2Graph.setText("Show Live Line Graph"); swO2Graph.setChecked(o2Graph); swO2Graph.setPadding(0, 0, 0, 30); layout4.addView(swO2Graph);

        TextView txtO2Mob = new TextView(dialogContext); txtO2Mob.setText("Mobile Data Tracking"); layout4.addView(txtO2Mob);
        Spinner spO2Mob = new Spinner(dialogContext);
        spO2Mob.setAdapter(mobOverlayAdapter); spO2Mob.setSelection(o2Mob); spO2Mob.setPadding(0, 10, 0, 30); layout4.addView(spO2Mob);

        Switch swO2Wifi = new Switch(dialogContext); swO2Wifi.setText("Show Today's WiFi Data Usage"); swO2Wifi.setChecked(o2Wifi); swO2Wifi.setPadding(0, 0, 0, 30); layout4.addView(swO2Wifi);

        TextView txtO2FgApp = new TextView(dialogContext); txtO2FgApp.setText("Foreground App Tracking Mode"); layout4.addView(txtO2FgApp);
        Spinner spO2FgMode = new Spinner(dialogContext); 
        spO2FgMode.setAdapter(fgAdapter); spO2FgMode.setSelection(o2Fg); spO2FgMode.setPadding(0, 10, 0, 30); layout4.addView(spO2FgMode);

        createHeader.accept(new Object[]{layout4, "OVERLAY 2 POSITION"});
        TextView txtO2Align = new TextView(dialogContext); txtO2Align.setText("Horizontal Alignment"); layout4.addView(txtO2Align);
        Spinner spO2Align = new Spinner(dialogContext); spO2Align.setAdapter(alignAdapter); spO2Align.setSelection(o2Align); spO2Align.setPadding(0, 10, 0, 30); layout4.addView(spO2Align);

        TextView txtO2X = new TextView(dialogContext); txtO2X.setText("Position X: " + o2X); layout4.addView(txtO2X);
        SeekBar sbO2X = new SeekBar(dialogContext); sbO2X.setMax(metrics.widthPixels); sbO2X.setProgress(o2X); sbO2X.setPadding(0, 10, 0, 30); layout4.addView(sbO2X);
        TextView txtO2Y = new TextView(dialogContext); txtO2Y.setText("Position Y: " + o2Y); layout4.addView(txtO2Y);
        SeekBar sbO2Y = new SeekBar(dialogContext); sbO2Y.setMax(metrics.heightPixels); sbO2Y.setProgress(o2Y); sbO2Y.setPadding(0, 10, 0, 30); layout4.addView(sbO2Y);


        // --- TAB SWITCHER LOGIC ---
        Consumer switchTab = new Consumer() {
            accept(Object indexObj) {
                int index = (Integer) indexObj;
                tabGeneral.setTextColor(index == 0 ? activeTabColor : inactiveTabColor);
                tabNotif.setTextColor(index == 1 ? activeTabColor : inactiveTabColor);
                tabO1.setTextColor(index == 2 ? activeTabColor : inactiveTabColor);
                tabO2.setTextColor(index == 3 ? activeTabColor : inactiveTabColor);
                scroll1.setVisibility(index == 0 ? View.VISIBLE : View.GONE);
                scroll2.setVisibility(index == 1 ? View.VISIBLE : View.GONE);
                scroll3.setVisibility(index == 2 ? View.VISIBLE : View.GONE);
                scroll4.setVisibility(index == 3 ? View.VISIBLE : View.GONE);
            }
        };
        tabGeneral.setOnClickListener(new View.OnClickListener() { onClick(View v) { switchTab.accept(0); }});
        tabNotif.setOnClickListener(new View.OnClickListener() { onClick(View v) { switchTab.accept(1); }});
        tabO1.setOnClickListener(new View.OnClickListener() { onClick(View v) { switchTab.accept(2); }});
        tabO2.setOnClickListener(new View.OnClickListener() { onClick(View v) { switchTab.accept(3); }});
        switchTab.accept(0); 

        // --- LIVE LISTENERS ---
        sbNotifIconSize.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) { int newSize = progress + 50; txtNotifIconSize.setText("Icon Text Size: " + newSize + "%"); if (fromUser) networkSpeedApi.get("setNotifIconSize").accept(newSize); }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        });
        sbBgRadius.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) { txtBgRadius.setText("Background Corner Radius: " + progress); if (fromUser) networkSpeedApi.get("setBgRadius").accept(progress); }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        });
        sbInterval.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) { txtInterval.setText("Update Interval: " + (progress + 1) + " sec"); }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        });

        // Overlay 1 Position Logic
        spO1Align.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            onItemSelected(AdapterView parent, View view, int position, long id) {
                sbO1X.setEnabled(position == 0);
                if(networkSpeedApi.get("setAlign1") != null) networkSpeedApi.get("setAlign1").accept(new Integer(position));
            }
            onNothingSelected(AdapterView parent) {}
        });
        sbO1X.setEnabled(o1Align == 0);
        SeekBar.OnSeekBarChangeListener pos1Listener = new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                if (fromUser) { if (seekBar == sbO1X) txtO1X.setText("Position X: " + progress); if (seekBar == sbO1Y) txtO1Y.setText("Position Y: " + progress); networkSpeedApi.get("setPosition1").accept(new int[]{sbO1X.getProgress(), sbO1Y.getProgress()}); }
            }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        };
        sbO1X.setOnSeekBarChangeListener(pos1Listener); sbO1Y.setOnSeekBarChangeListener(pos1Listener);

        // Overlay 2 Position Logic
        spO2Align.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            onItemSelected(AdapterView parent, View view, int position, long id) {
                sbO2X.setEnabled(position == 0);
                if(networkSpeedApi.get("setAlign2") != null) networkSpeedApi.get("setAlign2").accept(new Integer(position));
            }
            onNothingSelected(AdapterView parent) {}
        });
        sbO2X.setEnabled(o2Align == 0);
        SeekBar.OnSeekBarChangeListener pos2Listener = new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                if (fromUser) { if (seekBar == sbO2X) txtO2X.setText("Position X: " + progress); if (seekBar == sbO2Y) txtO2Y.setText("Position Y: " + progress); networkSpeedApi.get("setPosition2").accept(new int[]{sbO2X.getProgress(), sbO2Y.getProgress()}); }
            }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        };
        sbO2X.setOnSeekBarChangeListener(pos2Listener); sbO2Y.setOnSeekBarChangeListener(pos2Listener);

        SeekBar.OnSeekBarChangeListener padListener = new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                if (fromUser) { if (seekBar == sbPadX) txtPadX.setText("Padding Horizontal: " + progress); if (seekBar == sbPadY) txtPadY.setText("Padding Vertical: " + progress); networkSpeedApi.get("setPadding").accept(new int[]{sbPadX.getProgress(), sbPadY.getProgress()}); }
            }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        };
        sbPadX.setOnSeekBarChangeListener(padListener); sbPadY.setOnSeekBarChangeListener(padListener);
        sbSize.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) { int newSize = progress + 8; txtSizeLabel.setText("Display Size: " + newSize); if (fromUser) networkSpeedApi.get("setTextSize").accept(newSize); }
            onStartTrackingTouch(SeekBar seekBar) {} onStopTrackingTouch(SeekBar seekBar) {}
        });
        spTf.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            onItemSelected(AdapterView parent, View view, int position, long id) {
                String tfVal = "bold"; if (position == 0) tfVal = "normal"; else if (position == 2) tfVal = "italic"; else if (position == 3) tfVal = "bold_italic"; networkSpeedApi.get("setTypeface").accept(tfVal);
            }
            onNothingSelected(AdapterView parent) {}
        });
        spNotifMob.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() { onItemSelected(AdapterView parent, View view, int position, long id) { networkSpeedApi.get("setNotifMobileMode").accept(new Integer(position)); } onNothingSelected(AdapterView parent) {} });

        builder.setTitle("Network Speed Settings");
        builder.setView(mainLayout);

        builder.setPositiveButton("Save", new DialogInterface.OnClickListener() {
            onClick(DialogInterface dialog, int which) {

                int tfPos = spTf.getSelectedItemPosition();
                String tfVal = "bold"; if (tfPos == 0) tfVal = "normal"; else if (tfPos == 2) tfVal = "italic"; else if (tfPos == 3) tfVal = "bold_italic";

                try {
                    config.put("plan_type", spPlanType.getSelectedItemPosition());
                    config.put("monthly_reset_day", sbResetDay.getProgress() + 1);
                    config.put("custom_cycle_days", sbCustomDays.getProgress() + 1);
                    config.put("custom_cycle_anchor", anchorCal.getTimeInMillis());

                    String limStr = edtLimit.getText().toString();
                    if(limStr.isEmpty()) limStr = "0";
                    config.put("data_limit_mb", Integer.parseInt(limStr));

                    config.put("use_notification", swNotif.isChecked());

                    config.put("short_units", swUnits.isChecked());
                    config.put("drop_shadow", swShadow.isChecked());

                    // Global Overlay Config
                    config.put("hide_fullscreen", swHideFs.isChecked());
                    config.put("hide_lockscreen", swHideLock.isChecked());
                    config.put("overlay_auto_hide", swOverlayHideZero.isChecked());
                    config.put("overlay_active_only", swOverlayActiveOnly.isChecked());
                    config.put("overlay_click_task", swOverlayClickTask.isChecked());
                    config.put("overlay_long_click_task", swOverlayLongClickTask.isChecked());

                    // Overlay 1
                    config.put("use_overlay1", swO1.isChecked());
                    config.put("o1_show_speed", swO1Speed.isChecked());
                    config.put("o1_format_separate", swO1Sep.isChecked());
                    config.put("o1_show_graph", swO1Graph.isChecked());
                    config.put("o1_mobile_mode", spO1Mob.getSelectedItemPosition());
                    config.put("o1_show_wifi", swO1Wifi.isChecked());
                    config.put("o1_fg_mode", spO1FgMode.getSelectedItemPosition());
                    config.put("o1_align", spO1Align.getSelectedItemPosition());
                    config.put("o1_pos_x", sbO1X.getProgress());
                    config.put("o1_pos_y", sbO1Y.getProgress());

                    // Overlay 2
                    config.put("use_overlay2", swO2.isChecked());
                    config.put("o2_show_speed", swO2Speed.isChecked());
                    config.put("o2_format_separate", swO2Sep.isChecked());
                    config.put("o2_show_graph", swO2Graph.isChecked());
                    config.put("o2_mobile_mode", spO2Mob.getSelectedItemPosition());
                    config.put("o2_show_wifi", swO2Wifi.isChecked());
                    config.put("o2_fg_mode", spO2FgMode.getSelectedItemPosition());
                    config.put("o2_align", spO2Align.getSelectedItemPosition());
                    config.put("o2_pos_x", sbO2X.getProgress());
                    config.put("o2_pos_y", sbO2Y.getProgress());

                    // Notification
                    config.put("show_down_up_speed", swDownUp.isChecked());
                    config.put("notif_mobile_mode", spNotifMob.getSelectedItemPosition());
                    config.put("notif_show_wifi", swNotifWifi.isChecked());
                    config.put("notif_active_only", swNotifActiveOnly.isChecked());
                    config.put("show_on_lockscreen", swNotifLock.isChecked());

                    config.put("update_interval", sbInterval.getProgress() + 1);

                    config.put("padding_x", sbPadX.getProgress());
                    config.put("padding_y", sbPadY.getProgress());
                    config.put("text_size", sbSize.getProgress() + 8);
                    config.put("notif_icon_size", sbNotifIconSize.getProgress() + 50);
                    config.put("bg_radius", sbBgRadius.getProgress());
                    config.put("typeface", tfVal);

                    config.put("use_custom_colors", swCustomColors.isChecked());
                    config.put("color_bg", liveColors[0]);
                    config.put("color_down", liveColors[1]);
                    config.put("color_up", liveColors[2]);
                    config.put("color_total", liveColors[3]);
                    config.put("color_mobile", liveColors[4]);
                    config.put("color_wifi", liveColors[5]);
                    config.put("color_fg_app", liveColors[6]);
                    config.put("color_warn", liveColors[7]);
                    config.put("color_crit", liveColors[8]);
                    config.put("color_graph", liveColors[9]);

                    tasker.setVariable("NetworkSpeedConfig", config.toString());
                } catch (Exception e) {}

                networkSpeedApi.get("reloadConfig").run();
                activity.finish();
            }
        });

        builder.setNegativeButton("Cancel", new DialogInterface.OnClickListener() { onClick(DialogInterface dialog, int which) { dialog.cancel(); } });

        builder.setOnCancelListener(new DialogInterface.OnCancelListener() {
            onCancel(DialogInterface dialog) {
                // Instantly wipe memory preview and reload exact disk configuration
                networkSpeedApi.get("reloadConfig").run();
                activity.finish();
            }
        });

        builder.setCancelable(true);
        AlertDialog dialog = builder.create();
        dialog.show();

        Window window = dialog.getWindow();
        if (window != null) {
            settingsBgColor = isDark ? Color.parseColor("#212121") : Color.parseColor("#FFFFFF");
            window.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(settingsBgColor));
            window.setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT);
        }
    }
});
